quests[62801] = { id = 62801, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Call of Fate", description = "I am the Arbiter's fatescribe. It is my duty to observe the strands of destiny that the Purpose lays before us.\n\nFate flows through you, mortal, as you journey through the Shadowlands. And now it offers you... a choice.\n\nReturn to Oribos, {name}, that I might help guide your path.\n\nThe Purpose is our way.", completion = "Welcome, mortal.\n\nAllow me to explain the choice that the Purpose has set before you.", objectives = "Meet Fatescribe Roh-Tahl in Oribos.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62804] = { id = 62804, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Filling the Tanks", description = "<The containment pack appears to be intact, albeit empty. Perhaps refilling it with the appropriate mixture of liquids will render it functional once more.\n\nSlaying the correct combination of slimes should provide all the fluid necessary.>", completion = "An amazing find! You seem to have salvaged a fully charged unit... just throw this switch to activate it!", objectives = "Slay the variety of slimes to fill the tanks with fluid.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62807] = { id = 62807, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forest Refugees", description = "Some of those displaced by the fallen groves have made a home for themselves at the base of the Heart of the Forest.\n\nHibernal Hollow is fortunate. We have supplies, when they may not.\n\nIf you would, bring these to Flwngyrr. They care for the refugees there.", completion = "Many cries call in the night. Many creatures seek shelter.\n\nThis is a refreshing breeze.", objectives = "Bring Hibernal Hollow supplies to Flwngyrr in the Heart of the Forest.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62832] = { id = 62832, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Friends in Dark Places", description = "Even with all your aid, our sanctum will grow weaker without souls willing to help us.\n\nMany souls that may have been destined for Bastion are trapped within the Maw. If you can find a way to free them, they will help us restore Elysian Hold's power.\n\nSeek out what aid you can and do what we cannot, Maw Walker. Our very future may depend on it.", completion = "Back again so soon, Maw Walker?", objectives = "Find Ve'nari in the Maw.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62833] = { id = 62833, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Hero of Great Renown", description = "As you gain renown across the Shadowlands, you will draw others to our cause. Some may provide resources; some may offer direct support.\n\nElspeth Larink will be responsible for putting their contributions to use. Speak with her to learn more.", completion = "For the sake of the souls we defend, we must never falter.", objectives = "Speak with Elspeth Larink.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62834] = { id = 62834, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glorious Ambition", description = "The renown you earn through your deeds can and will greatly benefit our covenant. Our ambition is not confined within the borders of Maldraxxus, after all.\n\nAllow me to demonstrate what we achieve as you gain renown.", progress = "Talent is nothing without ambition.", completion = "Surrender is the ultimate failure.", objectives = "Examine your Renown with the Necrolord Covenant.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62835] = { id = 62835, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Call to Service", description = "We may hold the Seat of the Primus, but it will do us no good without the anima to power it.\n\nAs you fight beside our troops on the battlefield, seek out opportunities to recover anima to support the war effort.\n\nSpeak with Sergeant Romark. He can offer you additional guidance.", completion = "There is much to be done, Maw Walker.", objectives = "Speak with Sergeant Romark.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62836] = { id = 62836, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Signs of the Lion", description = "Thanks to your efforts, Thrall, Jaina Proudmoore, and Baine Bloodhoof are safe. Yet so long as the Jailer holds any hero of Azeroth, I fear he has power over us all.\n\nIt seems Anduin has been taken deeper into the tower than the others. Before I risk peering inside, you must make one last attempt to find him.\n\nYou say the Jailer spoke of honing a weapon. I fear we are running out of time.\n\nDo not relent, {name}. Search the twisting corridors of Torghast for any sign of the Young Lion.", progress = "Did you find any sign of Anduin?", completion = "Three sure signs of Anduin's presence, yet no sign of him.\n\nThis is dire news indeed.", objectives = "Enter Torghast and explore the Twisting Corridors for any sign of Anduin Wrynn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62837] = { id = 62837, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hopeful News", description = "The terms of our bargain have been met. You may depart with the souls you acquired.\n\nPerhaps the fate of this \"Baine\" is of interest to you or your allies. I suggest you return to Oribos and consult them.\n\nNo need to rush. After all, those held within Torghast are tortured for centuries.\n\nKindly remember not to tell anyone about our arrangement. Discretion is key between business partners, after all.", completion = "{name}! The darkness of the Maw lingers upon you. What news do you bring?", objectives = "Speak with Bolvar Fordragon in Oribos.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62839] = { id = 62839, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anima is Strength", description = "You are victorious, Maw Walker. And with your success, our forces grow stronger.\n\nStay alert. Your strength will be called upon again soon enough.\n\nBring the anima you recovered to Akradia Moa at once. She will ensure its proper storage.", completion = "You walk with the stride of victory, Maw Walker. Do you bring anima?", objectives = "Speak to Arkadia Moa", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62840] = { id = 62840, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Reservoir", description = "With anima in short supply, Baroness Draka has tasked me with carefully managing our reserves as they are needed.\n\nYou may deposit any anima you recover into the reservoir here. Be assured that the Necrolords will defend it at all costs.", objectives = "Deposit Anima into your sanctum's Reservoir.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62843] = { id = 62843, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Soul Contact", description = "Your reputation precedes you, Maw Walker... braving the Maw and bringing Baron Mograine back in one piece...\n\nThat was most impressive!\n\nWith our dire shortage of souls, we'll need you to do that again. Bring us more willing souls so we can restore this sanctum's power!\n\nSeek out the broker who aided you before and ask if she will do so again. You may need her.", completion = "Back again so soon, Maw Walker?", objectives = "Speak to Ve'nari in the Maw.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62844] = { id = 62844, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Draka", description = "Baine suffers within Torghast, but at least we know that he yet lives.\n\nRushing to his rescue would prove disastrous without a plan of attack. I will do what I can to prepare one.\n\nIn the meantime, you received a summons from Baroness Draka asking that you return to the Seat of the Primus.\n\nThe Necrolords are the key to saving the Shadowlands, {name}. I suggest you return to them as soon as you are able.", completion = "You have returned, Maw Walker. \n\nGood. We have much to do.", objectives = "Report to Baroness Draka at the Seat of the Primus in Maldraxxus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62845] = { id = 62845, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bringing It All Together", description = "With all of the houses against us, our forces are hard pressed to hold the line.\n\nThe souls you rescued from the Maw will help strengthen our position and bolster our defenses.\n\nBring them to Arkadia Moa. She will know how best to put them to use and empower our sanctum.", completion = "I could feel the presence of those souls as soon as you brought them here. Their potential will increase our power!", objectives = "Speak to Arkadia Moa.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62846] = { id = 62846, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sanctum Improvements", description = "Your will to succeed is strong, Maw Walker. With the anima and the souls you have recovered, we can now begin to unlock our sanctum's true potential.\n\nAs we acquire more souls and more anima, we can gain even greater power from the Seat of the Primus. Remain relentless in your pursuit, and victory will be ours.", progress = "This is only the beginning.", completion = "When it comes to matters like these, patience is as important as strength. In time, our power will grow vast and unmatched.", objectives = "Start a Sanctum Upgrade.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62848] = { id = 62848, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Conduits, What Are They For?", description = "While the benefits of soulbinding are substantial, you may strengthen them further through the use of conduits.\n\nConduits act to channel the anima of our bond in a myriad of ways, vastly increasing both of our potential.\n\nLet us test out the ones I have given you. Fear not--many others like it can be found throughout the Shadowlands.", progress = "This is an important lesson, my apprentice.", completion = "Our bond will grow in strength over time, but for now your training is complete.", objectives = "Add the Conduits to the Forge of Bonds, then apply one to a slot on Plague Deviser Marleth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62849] = { id = 62849, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paragon of the Court of Harvesters", description = "Maw Walker. \n\nYour efforts have provided the Court of Harvesters a decisive edge in their ongoing conflict with the zealots and sycophants who cling to the lost cause of Sire Denathrius.\n\nIf you will join me in Darkhaven we can express our gratitude to you in a more... physical... way. \n\nWith treasure, of course.", completion = "Consider this the first of many rewards that we might provide for your continued efforts. Your continued efforts towards the agenda of the Court of Harvesters ensures the long term success of Revendreth, and the opportunity for additional rewards for you.", objectives = "Speak with Mistress Mihaela in Darkhaven.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62850] = { id = 62850, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paragon of the Ascended", description = "Maw Walker. \n\nYour efforts have provided the Ascended with a decisive edge in their goals.\n\nWe have rewards for you, and thanks.", completion = "Continue to achieve the goals of the Ascended and we shall have treasures for you as a reward.", objectives = "Speak with Adjutant Nikos in Hero's Rest in Bastion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62851] = { id = 62851, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paragon of the Undying Army", description = "Your continued advancement of the Undying Army objectives has earned you the continued respect of our forces. \n\nI have been authorized to provide you with a portion of recent spoils of war in gratitude. Please join me at the Seat of the Primus to collect these spoils at your earliest convenience.", completion = "The Undying Army salutes you and proffers this flotsam of war in honor of your continued assistance. Aid us further, and more will come.", objectives = "Speak with Nalcorn Talsen at the Theater of Pain.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62852] = { id = 62852, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paragon of the Wild Hunt", description = "Well met, {name}!\n\nYou have proven yourself to all of Ardenweald. We would grant you further rewards, for your valor and cunning on our behalf.\n\nMeet with me at the Heart of the Forest.", completion = "Continue your efforts on our behalf and we will bestow more gifts on you. I look forward to seeing what you do!", objectives = "Speak with Aithlyn at the Heart of the Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62855] = { id = 62855, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Edict of the Eternal Ones", description = "Death appears to function differently for you, Maw Walker. Alas, you have shed some of your stygia.\n\nReturn to the place of your passing, and you shall find what you left behind.", sourceObjective = "Recover your Dropped Stygia from your corpse.", sourceObjectiveStatus = "unverified-source-field" }
quests[62856] = { id = 62856, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Building Your Renown", description = "As you aid the court in your travels across the Shadowlands, your connection to us shall grow ever stronger.\n\nIn time, you will be able to reap the benefits of your growing Renown.\n\nOne of my most trusted and loyal followers, Rahel, has been watching you for some time. She can report as to your standing and the Renown you have garnered with my people.\n\nSpeak to her and she might explain better how this Renown might be best put to work.", completion = "Work with me and your legend will haunt the waking dreams of every venthyr in Revendreth.", objectives = "Speak with Rahel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62857] = { id = 62857, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Court's Bounty", description = "Venthyr are drawn to new things, so we are going to make you the figurehead of our Sanctum. \n\nAs your Renown throughout the Shadowlands grows, we will grow with you, accumulating power and influence we otherwise would not have access to. \n\nIt will fall to me to track your Renown and quantify it as a resource. A true currency of Courts, if you will. \n\nObserve.", progress = "With enough anima, anything is possible.", completion = "As you can see, some have already begun to take notice of you.", objectives = "Examine your Renown with Sinfall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62858] = { id = 62858, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return Lost Souls", description = "Souls continue to pour into the Maw. As long as this is still happening, we need to save as many as possible!\n\nThe Jailer twists the cycle of life and rebirth. This cannot be allowed to continue! We must thwart his plans.\n\nReturn to the Maw and rescue those that you can.", completion = "Oh, wonderful news!\n\nI will make sure these souls are well taken care of here in Ardenweald.", objectives = "Rescue Souls in the Maw.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62859] = { id = 62859, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return Lost Souls", description = "Souls continue to pour into the Maw. As long as this is still happening, we need to save as many as possible!\n\nThe Jailer twists the cycle of life and rebirth. This cannot be allowed to continue! We must thwart his plans.\n\nReturn to the Maw and rescue those that you can.", completion = "Oh, wonderful news!\n\nI will make sure these souls are well taken care of here in Ardenweald.", objectives = "Rescue Souls in the Maw.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62860] = { id = 62860, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return Lost Souls", description = "Souls continue to pour into the Maw. As long as this is still happening, we need to save as many as possible!\n\nThe Jailer twists the cycle of life and rebirth. This cannot be allowed to continue! We must thwart his plans.\n\nReturn to the Maw and rescue those that you can.", progress = "Were you able to save anyone?", completion = "Oh, wonderful news!\n\nI will make sure these souls are well taken care of here in Ardenweald.", objectives = "Rescue Souls in the Maw.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62861] = { id = 62861, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return Lost Souls", description = "Souls continue to pour into the Maw, circumventing the natural order of the Shadowlands.\n\nThe Jailer denies these souls their rightful eternities. Only you, Maw Walker, can set things right.\n\nReturn to the Maw and save all that you can.", completion = "Well done. They have been spared a truly cruel existence.", objectives = "Rescue 10 Souls from the Maw.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62862] = { id = 62862, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return Lost Souls", description = "Souls continue to pour into the Maw, circumventing the natural order of the Shadowlands.\n\nThe Jailer denies these souls their rightful eternities. Only you, Maw Walker, can set things right.\n\nReturn to the Maw and save all that you can.", completion = "Well done. They have been spared a truly cruel existence.", objectives = "Rescue 15 Souls from the Maw.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62863] = { id = 62863, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return Lost Souls", description = "Souls continue to pour into the Maw, circumventing the natural order of the Shadowlands.\n\nThe Jailer denies these souls their rightful eternities. Only you, Maw Walker, can set things right.\n\nReturn to the Maw and save all that you can.", progress = "There is no fate worse than the Maw.", completion = "Well done. They have been spared a truly cruel existence.", objectives = "Rescue 20 Souls from the Maw.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62864] = { id = 62864, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return Lost Souls", description = "Maw Walker, I'm sure you've seen firsthand the souls that continue to pour into the Maw. \n\nWe must act now to cut off the Jailer's power, denying him as many souls as possible. That power belongs to the Necrolords.\n\nI shall direct your efforts to save these souls, and help find them a place among the armies of Maldraxxus.\n\nReturn to the Maw and rescue those that you can.", completion = "Excellent Maw Walker. Our armies here will grow stronger with each soul you return.", objectives = "Rescue Souls in the Maw.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62865] = { id = 62865, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return Lost Souls", description = "Maw Walker, I'm sure you've seen first hand the souls that continue to pour into the Maw. \n\nWe must act now to cut off the Jailer's power, denying him as many souls as possible. That power belongs to the Necrolords.\n\nI shall direct your efforts to save these souls, and help find them a place among the armies of Maldraxxus.\n\nReturn to the Maw and rescue those that you can.", completion = "Excellent Maw Walker. Our armies here will grow stronger with each soul you return.", objectives = "Rescue Souls in the Maw.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62866] = { id = 62866, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return Lost Souls", description = "Maw Walker, I'm sure you've seen firsthand the souls that continue to pour into the Maw. \n\nWe must act now to cut off the Jailer's power, denying him as many souls as possible. That power belongs to the Necrolords.\n\nI shall direct your efforts to save these souls, and help find them a place among the armies of Maldraxxus.\n\nReturn to the Maw and rescue those that you can.", progress = "There is no fate worse than the Maw.", completion = "Excellent, Maw Walker. Our armies here will grow stronger with each soul you return.", objectives = "Rescue Souls in the Maw.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62867] = { id = 62867, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return Lost Souls", description = "Souls continue to pour into the Maw. \n\nTheir anima, our very lifeblood of the Shadowlands, is going with those souls to fuel the Jailer. You rescued me from the Maw. I see no reason you cannot pull more souls from that abyss. \n\nBring souls you rescue from the Maw to me and I shall see them put to better use. At least in Revendreth they have a chance of redemption.", completion = "A very good collection of souls. Not too broken, not too drained, and not too innocent.\n\nNever fear, their fate is better in our hands than the Jailer's.", objectives = "Rescue Souls in the Maw.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62868] = { id = 62868, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return Lost Souls", description = "Souls continue to pour into the Maw. \n\nTheir anima, our very lifeblood of the Shadowlands, is going with those souls to fuel the Jailer. You rescued me from the Maw. I see no reason you cannot pull more souls from that abyss. \n\nBring souls you rescue from the Maw to me and I shall see them put to better use. At least in Revendreth they have a chance of redemption.", completion = "A very good collection of souls. Not too broken, not too drained, and not too innocent.\n\nNever fear, their fate is better in our hands than the Jailer's.", objectives = "Rescue Souls in the Maw.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62869] = { id = 62869, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return Lost Souls", description = "Souls continue to pour into the Maw. \n\nTheir anima, our very lifeblood of the Shadowlands, is going with those souls to fuel the Jailer. You rescued me from the Maw. I see no reason you cannot pull more souls from that abyss. \n\nBring souls you rescue from the Maw to me and I shall see them put to better use. At least in Revendreth they have a chance of redemption.", completion = "A very good collection of souls. Not too broken, not too drained, and not too innocent.\n\nNever fear. Their fate is better in our hands than the Jailer's.", objectives = "Rescue Souls in the Maw.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62870] = { id = 62870, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Souls for Sinfall", description = "Baine suffers within Torghast, but at least we know that he yet lives.\n\nRushing to his rescue would prove disastrous without a plan of attack. I will see to preparing one.\n\nIn the meantime, I suggest you bring the souls you rescued back to Sinfall. \n\nDenathrius's machinations have left the venthyr poorly provisioned, and Prince Renathal will require all the souls he can muster.", completion = "Ah, so you were successful. As I knew you would be.\n\nNow, let us put these souls to use.", objectives = "Return the souls rescued from the Maw to Tenaval in Sinfall within Revendreth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62882] = { id = 62882, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Setting the Ground Rules", description = "Back to rescue more souls? How intrepid.\n\nThough I must say, your earlier escapade has drawn the Jailer's attention... and his ire. After all, none have successfully eluded him before. \n\nExcept for me.\n\nNow his forces are on high alert, hunting down any errant souls that the fabled Maw Walker may try to steal from him.\n\nIt has made things quite... inconvenient for me. If you and I are going to work together, we need to set a few ground rules.\n\nAnd you must be properly equipped.", progress = "Let us discuss the terms of our arrangement.", completion = "Take care of that Soulkeeper. I have no desire to go through the effort of procuring another.\n\nNow, let us get to business.", objectives = "Set the ground rules about working together with Ve'nari.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62883] = { id = 62883, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keeper of Great Renown", description = "As you grow in renown across the Shadowlands, the Heart of the Forest shall grow with you. \n\nSeek out Laurel, our Keeper of Renown. She will acquaint you with the magic that we bestow upon our huntsmen and huntresses.", completion = "<Laurel strums a little fanfare on her harp as you approach.>\n\nAh, our new champion and boon companion! Well met, {name}.", objectives = "Seek out Laurel the Heart of the Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62884] = { id = 62884, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Forest Will Sing Your Name", description = "<Laurel picks out an intricate melody on deft fingers, and sings.>\n\nThe keeper of word and deed, am I, \nthe weaver of song and lore.\nBoons are granted as you grow in Renown,\nfulfilling the oaths we swore.\n\nEach deed that you do is a seed of strength,\nwhich will blossom in fabulous power.\nSpeak with me now and see what awaits,\nour magic is yours to discover!", progress = "I cannot wait to compose a song for you!", completion = "<Laurel plays a triumphant flourish.>\n\nMay your story grow as branches reaching for the skies! As our roots grow deep into the earth!", objectives = "Examine your Renown with the Night Fae Covenant.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62886] = { id = 62886, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Call to Service", description = "The Heart of the Forest requires anima to be renewed and to grow.\n\nThe Wild Hunt will need your help to recover what we need. Together we strand strong.\n\nSpeak with Blodwyn. She has been guiding assistance to where it is most needed.", sourceObjective = "Speak with Blodwyn.", sourceObjectiveStatus = "unverified-source-field" }
quests[62890] = { id = 62890, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Who Shapes the Forest", description = "You have fulfilled your calling, Maw Walker, and brought calm to our forest.\n\nStay vigilant, for others will similarly call upon you in time.\n\nThe anima you have recovered will be of great use to the Heart of the Forest. Bring it to Zayhad. They will ensure it is safe until it is needed. You will find them deep in the roots of the Heart of the Forest.", completion = "The roots wilt without anima. With your gift, we may all grow.", objectives = "Find Zayhad in the Roots of the Heart of the Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62891] = { id = 62891, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Reservoir", description = "Groves wither, and our Queen weeps on barren soil. Anima, precious as water, now rare as snow. Our Queen gives of her own, shelters all beneath her boughs... but one tree does not a forest make.\n\nYour gift will be treasured and protected. Anima nourishes our roots, as hope nourishes our hearts. Ardenweald may yet flourish once more.", progress = "None to waste, and none shall be wasted. It will be safe until needed.", completion = "Through famine and drought, the forest shall endure. Our gratitude defies description.", objectives = "Deposit Anima into your sanctum's Reservoir.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62892] = { id = 62892, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Recover the Lost", description = "Anima and souls. Wind and rain. Ardenweald needs both to thrive.\n\nSouls meant for our boughs suffer in darkness. None escape the Maw... but you walk its shadows and return. You are their salvation.\n\nFlutterby shepherds the flock with care and compassion. Speak with her. Bring our lost souls home.", completion = "I'm so glad you're here! We have so many souls to save!", objectives = "Speak to Flutterby in the Heart of the Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62893] = { id = 62893, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Do What We Cannot", description = "Rumor has it that you've been to the Maw and back... and that you even made friends with a broker in there! \n\nSo many souls destined for Ardenweald are trapped in that dark realm. They need our help... and we need theirs! We can't cultivate the Heart of the Forest's magic without them.\n\nI know this is a lot to ask... but you may be our only hope of rescuing them. Please, venture into the Maw and do what we cannot. Ardenweald's future depends on it!", completion = "Back again so soon, Maw Walker?", objectives = "Find Ve'nari in the Maw.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62894] = { id = 62894, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flutterback", description = "Baine suffers within Torghast, but at least we know that he yet lives.\n\nRushing to his rescue would prove disastrous without a plan of attack. I will see to preparing one.\n\nIn the meantime, I suggest you bring the souls you rescued back to Ardenweald.\n\nThey deserve respite after their harrowing ordeal in the Maw, and they will surely prove vital to the Night Fae's efforts.", completion = "Welcome back! I am so glad you didn't get trapped in there! It means none of our hard work will go to waste!\n\n<Flutterby giggles.>\n\nWe've been busy!", objectives = "Report to Flutterby in the Heart of the Forest in Ardenweald.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62895] = { id = 62895, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Track Selection" }
quests[62896] = { id = 62896, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Track Selection" }
quests[62897] = { id = 62897, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Recovered Souls", description = "Oh, I wonder what sorts of shapes these souls might take!\n\nWords can't express how grateful we are that you saved them. Not only have you brought an end to their torment, but they might be willing to aid us as well. \n\nGo speak with Zayhad. They haven't been able to tend the forest in a long while, but that might be about to change. This is all so exciting!", completion = "Leaves on the tempestuous wind find safe haven.", objectives = "Speak to Zayhad.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62898] = { id = 62898, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The First New Growth", description = "Long have we lain dormant. With souls, with anima, we grow once more. \n\nA choice now awaits. How shall we grow? You may decide which flower blooms first.\n\nIn time, with more anima and willing souls, the whole garden will prosper. For now, a single blossom signals hope for the future.\n\nLady Moonberry will want to know of your choice. Seek her out once it is made.", completion = "Well, you've been busy! I believe we are once again in your debt.\n\nThankfully, I think I have just the gift to give you in return.", objectives = "Start a Sanctum Upgrade.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62899] = { id = 62899, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Endless Forest", description = "Well, that's all I have for you! Whew! You've been on a whirlwind tour of things around here, haven't you? Up and down and slantways and even into the Maw! Your head must be practically spinning.\n\n<Flutterby giggles.>\n\nYou should check in with Lady Moonberry and let her know your training is complete!\n\nShe probably won't quiz you on what you've learned.\n\nProbably.", completion = "Welcome to the Court of Night, {name}. I just know we're going to save Ardenweald! Oh, and the rest of the Shadowlands, too!\n\nAnd if we can't, and the forest withers away, and the Jailer breaks free from the Maw and plunges all of the realms eternal into crushing despair from which there is no return... \n\nThen at least we can say we had fun trying!", objectives = "Return to Lady Moonberry.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62900] = { id = 62900, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Conduit for Growth", description = "While our bond is powerful in and of itself, you can also enhance it through the use of conduits.\n\nConduits channel the anima between soulbinds in many different ways, increasing both of our potential in the process. They allow us to attune ourselves to each other's unique strengths.\n\nLet's use a few now. If they can further empower our bond, then they can aid us in protecting the forest.", progress = "We're going to do great things together.", completion = "You and Niya will grow together in time. But for now, your training is complete.", objectives = "Add the Conduits to the Forge of Bonds, then apply one to a slot on Niya.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62902] = { id = 62902, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anima is Power", description = "You did well, boss. Keep it up like that, right, and we just might 'ave a chance of survivin' this mess.\n\nKeep your eyes open, though. Word of success like this gets 'round and it's only a matter of time till uvvers come callin' for your 'elp.\n\nNow, right, all that anima you've recovered can be put to use 'round 'ere. Bring it down to Foreman Flatfinger. He'll ensure it stored away nice and secure.", completion = "Boss returns the victor! You got any anima on 'and?", objectives = "Speak to Foreman Flatfinger.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62903] = { id = 62903, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Reservoir", description = "With anima in short supply these days, I've been entrusted to manage the reserves 'till they be needed.\n\nGo 'ead and deposit any anima you collect into the reservoir 'ere. \nBe assured, It'll be safe an' secure in me care.", progress = "I assure you, this here reservoir is the safest place to keep Anima in all of Revendreth.", completion = "There we go, the anima is safe and secure now.", objectives = "Deposit Anima into your sanctum's Reservoir.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62904] = { id = 62904, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Souls Plight", description = "Anima enables us to do many fings, but this sanctum can not function on anima alone. It'll require the combined effort of many souls workin' togeffer to unlock its full potential.\n\nThe Soul Warden is eager to be of service ever since you rescued 'im from the Maw. Your unique ability 'ta brin' souls from there will prove useful to him.\n\nWhy don't you go pay 'im a visit?", completion = "I'm pleased to speak with you once again, Maw Walker.", objectives = "Speak to Tenaval.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62905] = { id = 62905, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back into the Darkness", description = "Souls continue to pour into the Maw, and with them the anima that could help us.\n\nYou were able to rescue me from that place. Can I count on your strength to repeat the same trick?\nPlease, get us more willing souls so we can bolster this sanctum's power.\n\nSeek out what aid you can and do what we can't, Maw Walker. You are our last, best, hope.", completion = "Back again so soon, Maw Walker?", objectives = "Find Ve'nari in the Maw.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62910] = { id = 62910, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Against Overwhelming Odds", description = "Your eternal enemy, the Horde, grow in strength and number throughout the Shadowlands. \n\nWill you and your comrades simply roll over and yield to their might? \n\nNo, I expect not. It seems that not even death has quelled your thirst for battle. \n\nIf you succeed in cutting down your foes, despite the odds, I will reward you handsomely.", completion = "Well done, {class}. Well done indeed.", objectives = "Slay 25 Level 60 Horde anywhere within the Shadowlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62914] = { id = 62914, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Coalition of the Willing", description = "The good people of Revendreth continue to suffer under the oppression of Denathrius's loyalists. We must bolster our forces before we can move openly against our former Master.\n\nThe willing souls you recovered from the Maw will prove a boon in these trying times.\n\nGo to Foreman Flatfinger. He has been searching for assistance with building enhancements for our sanctum. Together, we will see Sinfall reach its full potential.", completion = "Oi! Wut's 'at, then? New souls, is it? \n\nRight, they 'ave a bit of potential, they do. Many fings I can do 'round 'ere wif their 'elp.", objectives = "Speak to Foreman Flatfinger.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62915] = { id = 62915, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Home Improvement", description = "I've been finkin' of a bit of ways we could improve the place, but since you brought in all of the anima and souls to do it, I fink you should be the one to decide which improvement we start on first.\n\nDon't get overwhelmed. As you bring in more anima and find more willin' souls, we'll be able to bring more capabilities to the place. For now, a single upgrade will fit the bill.", progress = "Take your time. The first step's always the hard one.", completion = "Good choice. \n\nIt'll take some time for the construction work to finish, but good fings take time don't they?", objectives = "Start a Sanctum Upgrade.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62916] = { id = 62916, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Your Next Best Friend", description = "You looking for a new friend? Hoo-hoo!\n\nLots of stewards who are happy to be friend. Plus, current friend can take break! Maybe go to Cliffs of Respite, rest feet, eat cake...\n\n<Sika gets lost in a daydream.>\n\nHoo! Right!\n\nI call stewards. You make new friend!", progress = "New friends, new friends! Stewards love making new friends!", completion = "Hoo-hoo! Have fun with new friend!", objectives = "Select a new steward companion, then return to Sika.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62917] = { id = 62917, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shared Souls", description = "The power of the Harvesters flows through your mortal body. But you may wield even greater might by binding your soul to another.\n\nDoing so has no known drawbacks, but offers many advantages for both parties involved. \n\nThe Accuser will oversee the process. Meet her at the Forge of Bonds when you are ready.", sourceObjective = "Meet The Accuser at the Forge of Bonds.", sourceObjectiveStatus = "unverified-source-field" }
quests[62918] = { id = 62918, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Binding Power", description = "The power of the Harvesters flows through your mortal body. But you may wield even greater might by binding your soul to another. \n\nTo soulbind with another is not an irrevocable bond. However, it is not to be entered into lightly.\nYou will experience one another's pasts. Your hopes, fears, dreams, your very memories--if any still linger. You will become kindred spirits in the truest sense.\n\nOnce complete, your connection will transcend physical space and make you stronger in more than mere brawn.", completion = "You have lived an... interesting life, thus far. I will endeavor to make it even more so.", objectives = "Complete the soulbinding ritual.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62919] = { id = 62919, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strengthening the Bond", description = "Do you feel it, too? Our connection is stronger than I imagined could be possible. \n\nI have been told that the bond will continue to grow over time, though we do have the ability to accelerate the process. \n\nSinfall needs our strength. Perhaps it is best we engage in this method now.", progress = "This will benefit us both.", completion = "We will accomplish much together.", objectives = "Use the Forge of Bonds to strengthen your bond with Nadjia.\n\nDo so by selecting a power and activating it.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62920] = { id = 62920, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Conduit For Change", description = "While the powers from your bond are substantial, you may also strengthen the bond further through the use of conduits.\n\nConduits act to channel the energy of your soulbind into your form more directly, increasing your potential in many ways.\n\nUse the ones I have given you as a test of this power, but fear not--you will find others in your travels.", progress = "This step is crucial for your advancement.", completion = "Your soulbind will strengthen over time, but for now your training is complete.", objectives = "Add the Conduits to the Forge of Bonds, then apply one to a slot on Nadjia the Mistblade.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62921] = { id = 62921, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Our True Purpose", description = "We are grateful for this partnership, Maw Walker. \n\nWith your help, Renathal will lead us into a new era, one that will see Revendreth reclaim its true purpose. \n\nReturn to him now so that the real work can begin.", completion = "I hope you've found everything to your liking.", objectives = "Return to Prince Renathal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62928] = { id = 62928, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blueprint: Ring of Warding", description = "<You have discovered plans for a defensive ward that may give your soulbinds an edge in the Path of Ascension.\n\nDactylis should be able to help you with crafting this piece of equipment.>", completion = "I see you have retrieved a new blueprint. I look forward to assisting you in your crafting.", objectives = "Bring the Blueprint: Ring of Warding to Dactylis.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62932] = { id = 62932, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Explore Torghast", description = "Baine is safe, but our other allies are still prisoners of the Jailer. They remain in grave peril.\n\nTorghast is a constantly changing place, shifting according to the will of its master. It may be impossible to track them through normal means.\n\nEnter its cell blocks and see what information you can find. Seek any clue that might lead us to our missing friends, and bring it back to me.", progress = "What did you find?", completion = "<Bolvar studies the object intently.>\n\nI sense a familiar essence. The holder of this key may have been involved in the capture of Jaina Proudmoore.\n\nI require time for further research. I will contact you once I determine our next course.", objectives = "Explore Torghast for clues to locate your allies.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62935] = { id = 62935, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Remnants of Hope", description = "I studied the key you brought back from Torghast, {name}.\n\nIt confirms that Jaina Proudmoore is still being held somewhere in the tower. However we do not know precisely where.\n\nCountless souls are captive inside that wretched place. A few may be intact, but many are shattered and broken.\n\nTake pity upon the remnants and free those you can. Perhaps they will be able to aid our search.", completion = "It is good that you saved those tortured souls, {name}. A pity none could help our cause. \n\nI must ponder our path forward. You will hear from me again when I know how to best proceed.", objectives = "See if you can gain any new insights from the trapped Soul Remnants in Torghast.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62938] = { id = 62938, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Information for a Price", description = "We must continue our search for Jaina Proudmoore. I have a new strategy to suggest.\n\nSince arriving in Oribos, I have been approached by many of the brokers. Some ask questions, others offer help--for a price.\n\nYou have encountered others of their kind inside Torghast. They may possess information we can use, though I doubt they will part with it freely.\n\nSeek them out and appeal to their avarice. Offer to pay for whatever information they possess.", progress = "A promising lead.", completion = "It seems the greed of the brokers has proved useful.\n\nYou may have acquired exactly what we need.", objectives = "Question the Brokers trapped inside Torghast.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62951] = { id = 62951, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Path of Ascension: Kleia", description = "Artemede has been personally training Kleia, running her through combat meditations and drills.\n\nShe has come far, and she is prepared to take on another trial in the Path of Ascension.\n\nReturn to the coliseum and guide her as her tactician so that she may reach victory.", completion = "As we expected. Kleia's strength continues to grow.", objectives = "Win any Path of Ascension trial as Kleia.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62952] = { id = 62952, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Path of Ascension: Pelagos", description = "Though combat is not his strong suit, Pelagos has been reading, meditating, and training to better himself on the Path.\n\nWe believe he is ready to seek victory.\n\nHe requests you by his side to help him strategize. He is stronger with the help of his friends.", completion = "One day, Pelagos will need to face challenges on his own to grow.\n\nFor now, the comfort and support of his soulbinds is exactly what he needs.", objectives = "Win any Path of Ascension trial as Pelagos.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62953] = { id = 62953, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Path of Ascension: Mikanikos", description = "Mikanikos has been hard at work at the Eternal Forge, calibrating Bron and tuning his combat procedures.\n\nHe is confident in his recent changes, and requests permission to attempt another trial.\n\nEnter the Path with Mikanikos so that he may assess his goliath's strengths and weaknesses.", completion = "It seems Bron has grown stronger indeed!\n\nI look forward to seeing how Mikanikos uses this new knowledge to improve centurions as a whole.", objectives = "Win any Path of Ascension trial as Mikanikos.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62954] = { id = 62954, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Path of Ascension: Kalisthene", description = "Your soulbinds request your strategic mind in another trial.\n\nTheir sights this week are set on Kalisthene, that they may learn from the lessons her memory teaches.\n\nWhen you are able, report to Artemede to return to the Path of Ascension. Aid your soulbinds in defeating Kalisthene to prove their growth.", completion = "Congratulations on the victory. I look forward to hearing what your soulbinds have learned.", objectives = "Defeat Kalisthene in the Path of Ascension with any soulbind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62966] = { id = 62966, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Finding a Witness", description = "You have rescued two of our allies from Torghast, but Anduin and Thrall have yet to be found.\n\nThat tower's corridors are vast... seemingly endless. You could spend an eternity wandering those unholy halls.\n\nIn your expeditions, you have encountered many unfortunate prisoners. Perhaps one of them has seen or heard something that could guide our search.\n\nSeek out any captives that might have the information we need, {name}.", completion = "I am heartened to know that Thrall yet lives. By the Light, we will find him.\n\nI fear for Anduin. Darkness hungers for his soul.\n\nWe must make ready. You will hear from me when it is time to proceed.", objectives = "Look for a prisoner in Torghast who might know where Anduin or Thrall is being held.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62967] = { id = 62967, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prison of the Forgotten", description = "I discovered an interesting item off the Warden you killed in the tower. \n\nBest not to ask how I know what you do and where you do it within the tower. Let's just say, I have my ways.\n\nBut this key could lead to something interesting within Torghast. Or something horrible. Most likely horrible.\n\nYou ought to explore a bit and see what it unlocks.", completion = "<As you place the key into the device, it shudders for a moment and begins to unlock.>", objectives = "Figure out where to use the Key of the Forgotten.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62969] = { id = 62969, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lest the Trail Go Cold", description = "From what the captive dredger told you, it seems Thrall has been taken deep into Torghast. The torments he is enduring must be unimaginable.\n\nWe need to learn where he is being held before the trail goes cold.\n\nThe tower is vast and perilous. Search where you are able. Bring back any clues you find.\n\nGo carefully, {name}. The Jailer's eye is upon you.", progress = "Have you found anything to help us locate Thrall?", completion = "<Bolvar studies the totem.>\n\nYes, this could point us to Thrall's location.", objectives = "Enter Torghast and find something to help us locate Thrall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62970] = { id = 62970, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blueprint: Steward Mail Pouch", description = "<You have discovered plans for a steward sized pouch, perfect for carrying mail.\n\nDactylis should be able to help you with crafting this.>", completion = "I see you have retrieved a new blueprint. I look forward to assisting you in your crafting.", objectives = "Bring the Blueprint: Steward Mail Pouch to Dactylis.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62971] = { id = 62971, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blueprint: Gilded Abacus", description = "<You have discovered plans for a steward sized abacus, capable of calculating deposits and withdrawals at any distance.\n\nDactylis should be able to help you with crafting this.>", completion = "I see you have retrieved a new blueprint. I look forward to assisting you in your crafting.", objectives = "Bring the Blueprint: Gilded Abacus to Dactylis.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62976] = { id = 62976, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Artisan Tool Belt", description = "<The tool belt has many pouches and loops, and is outfitted with many tools and materials. \n\nIt will allow your steward to not only assist you with crafting, but also carry common trade goods.>", completion = "Tools for me? Wow! Love making things.\n\nLook forward to working together more!", objectives = "Summon your steward companion via Summon steward, then give them the steward Mail Pouch.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62981] = { id = 62981, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blueprint: Artisan Tool Belt", description = "<You have discovered plans for a well made tool belt, a perfect gift for your favorite steward.\n\nDactylis should be able to help you with crafting this.>", completion = "I see you have retrieved a new blueprint. I look forward to assisting you in your crafting.", objectives = "Bring the Blueprint: Artisan Tool Belt to Dactylis.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62984] = { id = 62984, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blueprint: Medallion of Service", description = "<You have discovered a donation plan to earn Medallions of Service, the respected Kyrian symbol of commendation. By donating materials to your sanctum, you can receive Medallions to enter the Path.\n\nDactylis should be able to help you facilitate this.>", completion = "I see you found the donation ratios for Medallions of Service. I look forward to rewarding you upon your contribution of materials.", objectives = "Bring the Blueprint: Medallion of Service to Dactylis.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62985] = { id = 62985, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dredging up a New Look", description = "If ye look around the muck pool I am sure you will find an armor dye. It might be nice to have the option to dye me belt a different color.", progress = "Did you find one?", completion = "We dredgers are an adaptable lot. If you find other dyes we will have options to dye my belt or even a doublet if you find one. Also, we be good at follicle control, so if you find any fetching posters of good lookin' folk give it to me and I will learn how to grow mine to match.", objectives = "Search enemies or discarded bottles in the Dredgewood for an armor dye.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62986] = { id = 62986, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blueprint: Vesper of Calling", description = "<You have discovered plans for a single use chime, capable of summoning courier Hermestes anywhere in the Shadowlands.\n\nDactylis should be able to help you with crafting this chime.>", completion = "I see you have retrieved a new blueprint. I look forward to assisting you in your crafting.", objectives = "Bring the Blueprint: Vesper of Calling to Dactylis.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62993] = { id = 62993, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Riddle of Death" }
quests[62995] = { id = 62995, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spiritforged Aegis", description = "<As you pick up the shield, your hands seem to lightly bounce off of it with ease.\n\nThis should help your soulbinds take a few hits in the Path of Ascension.>", completion = "Shield? Yes! Nice! I hold on for safe keeping.", objectives = "Bring the Spiritforged Aegis to Paolone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62996] = { id = 62996, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vial of Lichfrost", description = "<The vial, filled with a frosty liquid, is chill to the touch.\n\nThis should hinder your soulbinds' opponents in the Path of Ascension.>", completion = "Strange liquid... Wow! Cold! I hold on for safe keeping.", objectives = "Bring the Vial of Lichfrost to Paolone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62997] = { id = 62997, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blueprint: Vial of Lichfrost", description = "<You have discovered plans for a concoction that may freeze opponents in the Path of Ascension.\n\nDactylis should be able to help you with crafting this piece of equipment.>", completion = "I see you have retrieved a new blueprint. I look forward to assisting you in your crafting.", objectives = "Bring the Blueprint: Vial of Lichfrost to Dactylis.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62998] = { id = 62998, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ring of Warding", description = "<You place down the ring and are knocked back by a protective bubble.\n\nThis should force your soulbinds' opponents away from an area in the Path of Ascension.", completion = "Ring? Wow! Very nice! I hold on for safe keeping.", objectives = "Bring the Ring of Warding to Paolone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62999] = { id = 62999, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Croman", objectives = "Even if it doesn't bleed, we can still kill it.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63000] = { id = 63000, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blueprint: Charm of Focus", description = "<You have discovered plans for a charm that seems to energize your soulbinds in the Path of Ascension.\n\nDactylis should be able to help you with crafting this charm.>", completion = "I see you have retrieved a new blueprint. I look forward to assisting you in your crafting.", objectives = "Bring the Blueprint: Charm of Focus to Dactylis.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63002] = { id = 63002, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dangerous to Go Alone", description = "I trust you know well all that Elysian Hold can provide, but that alone will not be enough to thwart Denathrius.\n\nYou must have a soulbind to aid you, Maw Walker.\n\nSeek out Soulguide Daelia in the chamber below. She has prepared for the ritual.", completion = "I see even now that your soul burns brighter than most.", objectives = "Speak with Soulguide Daelia in the Sanctum of Binding.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63003] = { id = 63003, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Collective Soul", description = "You know conflict as well as any soldier in Maldraxxus, Maw Walker. But we do not fight alone.\n\nThere is great wisdom in leaning on the strengths of your allies. That is the Maldraxxi way.\n\nSpeak to Plague Deviser Marileth. He will show you how to soulbind and best reap its benefits.", completion = "I'm so pleased to see you again, my apprentice!", objectives = "Speak with Plague Deviser Marileth about the soulbinding process.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63006] = { id = 63006, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "For Queen and Grove!", description = "You have already done so much to help us since you first step foot in our realm! I'm so glad you decided to join our covenant.\n\nThere will be plenty of time for reminiscing later, though. You have an audience with the Winter Queen herself to go to!\n\nLet's not keep her waiting!", progress = "Welcome to the Hunt.", completion = "Your actions here will echo beyond the veil. Aid the forest, and all mortal worlds may yet be saved.", objectives = "Join the Night Fae Covenant.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63008] = { id = 63008, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Forge of Bonds", description = "To best serve the court and the forest, you must bond with another fae.\n\nIt is an ancient ritual, one which will grant you great strength to face the many trials ahead.\n\nFlutterby below will guide you further.", completion = "Oh, wow! I love guiding soulbinding! It's my favorite duty!", objectives = "Meet Flutterby at the Forge of Bonds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63022] = { id = 63022, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rule 6 Addendum: Save Me At Any Cost", description = "You! You, there! Wait!\n\nYou are the infamous Maw Walker, yes? I have heard much about you.\n\nPlease, help me! My compatriots have been drained of their essence. The Mawsworn are using it to fashion their foul runes.\n\nOne of them bound me here, and I am sure to be next on his list. You must slay him in order to free me!\n\nI can make it worth your while. I have collected a fair amount of stygia during my time in the Maw. It is yours, all of it, if you save me!", progress = "There is no time to waste. Hurry, before the Mawsworn return!", completion = "Not a moment too soon! Those fiends were just about to put the sword to me. \n\nHere, as we agreed, is your payment in stygia. \n\nThough truth be told, I owe you a great deal more than this. I have nothing left to offer... except for wisdom and warnings.", objectives = "Slay Runemaster Mavrok.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63029] = { id = 63029, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Highlord Calls", description = "We have received word from Highlord Fordragon urging you to return to him in Oribos at once.\n\nAll I know is it pertains to the Maw.\n\nYou should go to him with haste. Anything involving that dark place must be our top priority.", completion = "I have dire news, {name}.", objectives = "Report to Highlord Bolvar Fordragon in Oribos.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63030] = { id = 63030, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Highlord Calls", description = "Highlord Fordragon needs you in Oribos right away!\n\nI'm not sure of the details, but the messenger mentioned the Maw.\n\nYou should go to him as soon as you can. If the Maw is involved, it must be serious!", completion = "I have dire news, {name}.", objectives = "Report to Highlord Bolvar Fordragon in Oribos.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63031] = { id = 63031, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Acquisition: Crystallized Stygia", description = "<This shard of crystal appears to have broken off of one of the massive crystalline structures throughout the area. It thrums with untapped energy.\n\nVe'nari would likely be interested in any of these shards you come across.>", progress = "What have you collected, {class}?", completion = "Ah yes, the dormant stygia throughout the Maw will sometimes coalesce into forms such as this.\n\nYou were wise to bring this to me, {class}.", objectives = "Collect 10 Crystallized Stygia and return it to Ve'nari in the Maw.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63032] = { id = 63032, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Highlord Calls", description = "Highlord Fordragon has requested your presence in Oribos.\n\nWe know only that it involves the Maw.\n\nGo to him, and show him that the Maldraxxi will never falter. Even in the face of that dark place.", completion = "I have dire news, {name}.", objectives = "Report to Highlord Bolvar Fordragon in Oribos.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63033] = { id = 63033, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Highlord Calls", description = "A messenger from Oribos has informed us that Highlord Fordragon has requested your presence in Oribos.\n\nIt seems it pertains to the Maw... and the Master's plans, no doubt.\n\nI suggest you heed his summons, Maw Walker. We must leave nothing to chance.", completion = "I have dire news, {name}.", objectives = "Report to Highlord Bolvar Fordragon in Oribos.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63034] = { id = 63034, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Elysian Fields", description = "You must travel to Bastion, eternal home of the winged kyrian.\n\nDo not be fooled by their golden fields and shining spires--the kyrian have been weakened by the great anima drought, and face the brink of civil war against their own fallen brethren.\n\nThey will benefit greatly from your aid. Seek one known as Kalisthene in your new sanctum, Elysian Hold. She will direct you further.\n\nPathscribe Roh-Avonavi in the Ring of Transference above can provide transport.", completion = "Why have you come to our realm, mortal?", objectives = "Speak to Kalisthene at Elysian Hold in Bastion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63035] = { id = 63035, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Fresh Blade", description = "Though they were once unified in defending the Shadowlands, the houses of Maldraxxus have turned against each other.\n\nTheir armies clash within their realm and have even orchestrated an assault on Bastion. Now only the Necrolords remain loyal to the Primus.\n\nSpeak to Secutor Mevix at the Seat of the Primus in Maldraxxus. His tactical skills will ensure you are sent where you are most needed.\n\nPathscribe Roh-Avonavi in the Ring of Transference above can provide you with transportation.", completion = "Ah, another blade on our side! And you aren't even dead yet!", objectives = "Speak to Secutor Mevix at the Seat of the Primus in Maldraxxus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63036] = { id = 63036, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Restoring Balance", description = "Ardenweald is crucial to the cycle of rebirth for nature spirits that enter their realm.\n\nUnfortunately, the anima drought has led to the loss of entire groves--souls that will never complete their cycle.\n\nNow foes seek to destroy what remains of the once tranquil forests, threatening the already beleaguered Court of Night. \n\nLady Moonberry of the Court has requested aid. Pathscribe Roh-Avonavi in the Ring of Transference above can provide transport.", completion = "Welcome! What brings you to the Heart of the Forest?", objectives = "Speak to Lady Moonberry at the Heart of the Forest in Ardenweald.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63037] = { id = 63037, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dark Aspirations", description = "Prince Renathal has started a daring rebellion against his father, the nefarious Sire Denathrius who betrayed us all by pouring Revendreth's vast anima stores into the Maw.\n\nYou must travel to Revendreth and aid Renathal in his efforts. He is our best hope at restoring Revendreth to order.\n\nPathscribe Roh-Avonavi in the Ring of Transference above can provide transport.", completion = "And to what do I owe the pleasure of a mortal visiting Revendreth at such an...inopportune time?", objectives = "Speak to Prince Renathal in Sinfall in Revendreth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63038] = { id = 63038, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Guaranteed Delivery", description = "<The broker appears to be from Cartel Ve. Perhaps they were once an associate of Ve'nari.\n\nClutched in their hand is a list of items and a containment orb.\n\nFinishing this broker's task and sending the items back to Ve'nari will surely earn you some compensation.>", completion = "Excellent, {name}. I wondered what had become of that particular associate. \n\nIt pleases me to know that their demise was not a complete loss.", objectives = "Use the Containment Orb to send 8 Imprisoned Essences to Ve'nari.\n\nSuggested Players [3]", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63039] = { id = 63039, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Monument to Vengeance", description = "<Corpses of Ebon Blade knights litter the Crucible of the Damned, displaying the aftermath of your first foray into this desolate place.\n\nTheir sacrifice should not be forgotten.>", progress = "<This precipice is highly visible throughout the Maw. \n\nBuilding the monument here will surely draw the Jailer's ire.>", completion = "<The Ebon Blade monument radiates with energy from the fallen knights' runeblades.\n\nIt is a small tribute to their sacrifice, but it will have to do.>", objectives = "Collect 8 Ebon Runeblades and build a monument to the Ebon Blade's sacrifice in the Crucible of the Damned.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63040] = { id = 63040, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Guaranteed Delivery", description = "<The broker appears to be from Cartel Ve. Perhaps they were once an associate of Ve'nari.\n\nClutched in their hand is a list of items and a containment orb.\n\nFinishing this broker's task and sending the items back to Ve'nari will surely earn you some compensation.>", completion = "Excellent, {name}. I wondered what had become of that particular associate. \n\nIt pleases me to know that their demise was not a complete loss.", objectives = "Use the Containment Orb to send 5 Scrolls of Subjugation and 3 Tools of Constraint to Ve'nari.\n\nSuggested Players [3]", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63041] = { id = 63041, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Short-Supply Reward" }
quests[63043] = { id = 63043, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sundered Souls", description = "The traps... they didn't affect us before. Too many souls... escaping. \n\nThey... made new traps... tear apart fleeing souls...\n\n...too late for me. Destroy... so others might escape!", completion = "<With the rending traps disabled, the souls here should stand a better chance of escaping their captors.\n\nThough they may never escape the Maw, at least they have a chance of escaping the grim fate of becoming a mindless shade.>", objectives = "Destroy 10 Soulrend Traps in the Tremaculum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63044] = { id = 63044, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ratgusher" }
quests[63045] = { id = 63045, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feed Your Soul", description = "They... drained my anima... to fuel their ritual...\n\nSouls of great power are brought here... to this altar... and sacrificed to conjure unspeakable horrors bound to the Jailer.\n\nI was powerful once... Imbue me with the anima they stole... and I can be powerful again.\n\nThen, together... we will destroy the one who leads their efforts.", completion = "Quite the tale, {name}. Few motivations are as potent as revenge.", objectives = "Reclaim anima to empower the Vengeful Soul and defeat Inquisitor Moorlac with their help.\n\nSuggested Players [3]", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63046] = { id = 63046, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The End and the Beginning", description = "I am so happy you restored our connection to the Queen's Conservatory!\n\nIn light of this accomplishment, the Winter Queen has requested you attend her at the Grove of Awakening! \n\nYou will see first hand the purpose of Ardenweald and gain a greater understanding of our sacred charge before you too, take it upon yourself.\n\nHurry! Don't keep everyone waiting!", completion = "Welcome. Together we shall thrive!", objectives = "Learn about Wildseeds from the Winter Queen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63047] = { id = 63047, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Acquisition: Runeforged Shackles", description = "<The chains here are carved with domination runes, imbuing them with the magic needed to subdue the most powerful of the Mawsworn's prisoners.\n\nNo doubt Ve'nari could find some use in studying these runes.>", progress = "Another transaction?", completion = "Chains? Not exactly hard to find around here... wait, those runes...\n\nYou have a keen eye, indeed. The magic here is worth further study.", objectives = "Collect 9 Runeforged Shackles and return them to Ve'nari in the Maw.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63050] = { id = 63050, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Acquisition: Blazing Ingots", description = "<The runesmiths have imbued this ingot with an enchantment that causes it to burn with inextinguishable flames. \n\nIt is likely that this metal is used to empower the Mawsworn protectors of Zovaal's Cauldron. \n\nBringing some samples of this ore to Ve'nari could aid her attempts at unlocking the Jailer's secrets.>", progress = "What's this?", completion = "Intriguing. I had often wondered what differentiated the Cauldron's protectors from the rest of the Mawsworn.\n\nI hope these weren't too difficult for you to procure.", objectives = "Collect 12 Blazing Ingots and return them to Ve'nari in the Maw.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63051] = { id = 63051, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trust Issues", description = "Ah, Maw Walker! Allow me to introduce myself. I am Ve'rayn. I deal with assets and liabilities for Cartel Ve.\n\nI have heard that you are able to freely travel between Oribos and the Maw, a place of great interest to my cartel.\n\nWould you mind if I ask you a few questions about it?\n\nYou will, of course, be properly compensated for your time and information. They are the most valuable of commodities, after all.", completion = "Cartel Ve was asking you questions about me?\n\nI'm flattered. Make sure you never tell them anything.\n\nEver.\n\nCome. There's work to do.", objectives = "Answer Ve'rayn's questions about the Maw.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63052] = { id = 63052, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Step of Faith", description = "Our ascended fly across Bastion with ease, ensuring safety and prosperity across the realm.\n\nLong ago we established a network of anima gateways to help our aspirants, goliaths, and stewards traverse our realm more quickly.\n\nGo forth and activate the network once more, so that you too may be wherever you are needed in the mere blink of an eye.", completion = "It has been many eons since the anima gateways were active.", objectives = "Activate the Transportation Network.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63053] = { id = 63053, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "At a Moment's Notice", description = "No longer must you take a larion across Bastion, Maw Walker.\n\nWith our gateways active once more, you shall enjoy instantaneous travel wherever you are needed.\n\nDo note that you must still utilize a larion to return to Oribos or travel to the other realms.\n\nGive it a try and see for yourself.", progress = "It really is amazing, is it not?", completion = "In time we may open new destinations for our gateways. Haephus can direct you further.", objectives = "Use the Eternal Gateway to travel somewhere in Bastion, then use any Eternal Gateway to return to Elysian Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63054] = { id = 63054, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strength in Numbers", description = "Every soul in Maldraxxus has the potential for greatness, and we will need all we can muster if we hope to restore order to the Shadowlands.\n\nWith this addition to the sanctum, we can mobilize our forces and give them the chance to prove themselves on the field of battle.\n\nSeek out Merick Feldscar. He will see to the deployment of our soldiers.", completion = "Well met, {name}. Together, we will see our soldiers rule the battlefield.", objectives = "Activate the Command Table.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63055] = { id = 63055, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Powering the Portals", description = "The Primus once maintained a network of portals that linked the necropoli of Maldraxxus directly to the Seat of the Primus. The lack of anima and recent destruction of many of the necropoli have rendered those connections inactive.\n\nWith the anima you have provided us, we have managed to reconnect one of those portals. You shall once more be able to travel to one of our great necropoli... assuming it still exists.", completion = "It has been many eons since these portals have been active. It's most exciting!", objectives = "Activate the Transportation Network.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63056] = { id = 63056, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sanctum Upgrade: Mirror Network", description = "Right. So, we got a Scroll of Dark Empowerment ready for youz that should manifest 'em mirror frames for you. Pre'y standard work.\n\nThing is, after you going to need a proper mirror maker to get 'em up an' workin'. \n\nPrince Renathal might know a fang with the right skills. Best speak with him.", progress = "Enough anima in the right hands and we can construct whatever is needed in Revendreth.", completion = "A network of mirrors to translocate throughout the realm will prove invaluable.\n\nRumor suggests of the former mirror maker of the Master was lost in the Ember Ward rather recently. \n\nYou have proven to have a talent for convincing people to join our side.", objectives = "Use the Scroll of Dark Empowerment to conjure a Mirror Network.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63057] = { id = 63057, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Restoring Power", description = "Anima is power, {name}! \n\nWhen it was plentiful, the Primus ensured that his soldiers received all of the anima they required.\n\nNow, in the midst of this drought, the Maldraxxi fight amongst themselves for any anima they can find. \n\nAs our stockpile of anima grows, we can distribute it throughout Maldraxxus. It falls to us Necrolords to carry out the Primus's duty in his absence. \n\nSpeak to Yondare Hex. She will show you how to do so.", progress = "Yes, yes, you! You can help!", completion = "Long have I waited to weave anima across Maldraxxus once more.", objectives = "Activate the Anima Conductor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63058] = { id = 63058, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abominable Stitching and Me", description = "Constructs have formed the backbone of Maldraxxi armies in more wars than anyone can count. A well-constructed body can turn any soul into a potent frontline weapon.\n\nThere is an old abominable stitching table outside of the sanctum that could be used to build our own constructs. With the anima you've secured for our covenant, we should be able to restore it.\n\nReport to Miggsie once the work has begun. You can find her at Butchers Block.", progress = "You made the right choice.", completion = "You fixed the stitching table? That's great! Soon we'll be able to build our own constructs!", objectives = "Activate the Abomination Factory.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63059] = { id = 63059, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blink of an Eye", description = "This was once a long tauralus ride, but not anymore!\n\nBy simply stepping through this portal, you can now journey to the House of Eyes in an instant.\n\nThe House of Eyes may not be what it once was, but valuable allies can still be found in the ruins of their once great necropolis.\n\nTravel there now to test the portal's functionality.", progress = "It worked! That was most unexpected.", completion = "With more work, we can establish portals to other necropoli around the Shadowlands.", objectives = "Travel through the Nurakkir, House of Eyes portal, then use the Seat of the Primus portal to return.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63060] = { id = 63060, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rule 6 Footnote: Don't Forget Anything", description = "In the Maw, you must never forget to take everything with you.\n\nMany things crawl within the Beastwarrens. The runes you brought back indicate that something of interest may have been left behind by the brokers who were taken there.\n\nSee if you can find it.", completion = "You're back! Thank goodness... I thought my one chance at salvation had slipped away!\n\nYou will save me, yes?", objectives = "Look for whatever was left behind by the brokers in the Beastwarrens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63061] = { id = 63061, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Helping Hand", description = "We may have the stitching table, but it won't do us any good without someone to use it... someone like Rathan!\n\nI've heard that he's already gone to speak with the Necrolords. Perhaps if you meet with him, you could ask him to set up shop here.\n\nWith his assistance, we could be stitching abominations together in no time!", objectives = "Speak with Rathan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63062] = { id = 63062, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Torment for the Taking", description = "<A broker device has been abandoned here. It seems like it was being used to siphon energy from rifts of soul energy that have erupted in the area.\n\nThe brokers surely would not have sought to harness this energy if it didn't have a use. Perhaps you should finish what they started.>", completion = "You've found my siphoner. You are just full of surprises, Maw Walker.\n\nThe unique way that pain and suffering manifests physically in the Maw is a mystery... one which this energy you've collected may help unravel. \n\nWell done.", objectives = "Fill the Phasic Siphoner from the Soul Fissures in Detrithos and return it to Ve'nari in the Maw.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63063] = { id = 63063, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sanctum Upgrade: Mirror Network", description = "We got a Scroll of Dark Empowerment ready for youz that should manifest 'em mirror frames for you. Pre'y standard work.\n\nOnce you do the conjurin', then ol' Laurent should be able to work 'is magic as it were. Right proper glass guy he is.", completion = "Ah! At last, the tools I need are all in place. Now the real work can begin.", objectives = "Use the Scroll of Dark Empowerment to conjure a Mirror Network.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63064] = { id = 63064, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sanctum Upgrade: Command Table", description = "We got a Scroll of Dark Empowerment ready for youz that should manifest a command table for you. Not just any command table, but one of 'em magic ones that lets you issue orders from afar.\n\nTactician Sakaa insisted she be your wing for that one. Never much trusted 'em wings as they ain't too kind to us dredgers but put 'em in charge of war and even Maldraxxus flinches.", progress = "Maw Walker.", completion = "We have much to accomplish, and as resourceful as you are, you are not able to be in all places at once.", objectives = "Use the Scroll of Dark Empowerment to conjure a Command Table.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63065] = { id = 63065, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sanctum Upgrade: The Ember Court", description = "We got a Scroll of Dark Empowerment ready for youz that should provide you with enough resources to get one of 'em fancy parties the fangs are fond of.\n\nThe Mad Duke is the one you should chat with 'bout this one. He used to run all the court parties back before he got roasted.", completion = "Come, come, my friend!\n\nIt is time... for a PARTY!", objectives = "Use the Scroll of Dark Empowerment to begin the Ember Court.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63066] = { id = 63066, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sanctum Upgrade: Anima Conductor", description = "Right. So we got all this anima you been collecting.\n\nThing is, all that anima originally got squeezed out of the other realms. The Master, he was big on drainin' anything that weren't him. \n\nSo, we set up a Scroll of Dark Empowerment for you on the lower level. Should conjure somefin' strong enough for you to channel anima back into the Shadowlands, by way of Revendreth Wards. \n\nSeems to me there'd be some fringe benefits from somefin like that.", completion = "It is time to begin restoring anima to the Shadowlands.", objectives = "Use the Scroll of Dark Empowerment to conjure an Anima Conductor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63067] = { id = 63067, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Root Restoration", description = "Anima once flowed freely, but we have been thirsting. You bring us nourishment in times of trouble. We grow.\n\nWe may now help others and share our bounty.\n\nWatch our growth, then speak with Sesselie. They will guide you further.", progress = "Ah. You're here. Good.", completion = "We regrow with hope.", objectives = "Activate the Anima Conductor, then seek out Sesselie.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63068] = { id = 63068, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Settling Disputes", description = "In my search to find kyrian that would fit our purposes here, I have landed on two in particular -- Pelodis and Nemea.\n\nHowever, the two are involved in quite the rivalry, and struggle to focus their attention elsewhere. I propose that you aid them in settling their dispute so that they may focus on the task at hand.\n\nI doubt they shall work together, however, so you will need to pick one to aid us.", completion = "Ah, you come to aid in my dispute. Allow me to show you my ways.", objectives = "Meet with Pelodis at Forgefire Outpost or Nemea at Nemea's Retreat.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63069] = { id = 63069, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What They Know", description = "<It looks like this broker was gathering information before he met his unfortunate end. Ve'nari would likely be very interested in what he found.\n\nUnfortunately, his notes look to have been scattered far and wide by the local beasts.>", progress = "That book... that is a pathfinder's journal you carry!", completion = "It would seem that Cartel Ve has not given up their pursuit of the Maw.\n\nYou did well to bring me this pathfinder's journal. Whatever the cartel has learned about this place will surely serve us better than it would a corpse.", objectives = "Collect 18 Torn Journal Pages in the Hungering Wastes and return them to Ve'nari in the Maw.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63072] = { id = 63072, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Acquisition: Stygic Ore", description = "<The rock columns in this area are teeming with veins of a glowing, otherworldly metal. \n\nThe Mawsworn have employed souls to mine it, but it looks like they didn't last long.\n\nVe'nari could certainly find use for some of this ore, if you can manage to mine it.>", progress = "What do you carry, Maw Walker?", completion = "Fascinating, the metal here seems to be fabricated entirely of stygia!\n\nThere is much I can do with this. Take this reward, with my thanks.", objectives = "Collect 15 pieces of Stygic Ore in Marrow's Coppice and return them to Ve'nari in the Maw.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63073] = { id = 63073, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Mycelial Network", description = "Anima flows into the deepest of roots, feeding the mushrooms. Long has it been since we used the rings to travel across Ardenweald.\n\nRestore our connection to the mushroom network.", completion = "Hmmmmmmmmmmmmmmmmm. Normally we'd be seeing some mushrooms sprouting by now.", objectives = "Activate the Transportation Network.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63100] = { id = 63100, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Misery's Company", description = "<The husk of this poor soul has been stripped of everything, down to near nonexistence.\n\nThis suffering cannot continue. Save the others from their misery.>", objectives = "Kill 10 Hopeless Vessels in Gorgoa: River of Souls.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63101] = { id = 63101, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "XX REUSEME", description = "As you grow in renown across the Shadowlands, the Heart of the Forest shall grow with you. \n\nSeek out Laurel, our Keeper of Renown. She will acquaint you with the magic that we bestow upon our huntsmen and huntresses.", sourceObjective = "Seek out Laurel the Heart of the Forest.", sourceObjectiveStatus = "unverified-source-field" }
quests[63132] = { id = 63132, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Constellan Writ", description = "<The writing on the scroll changes rapidly. It likely holds ancient secrets that Ve'nari may find intriguing.>", completion = "<Ve'nari examines the writ.>\n\nQuite an interesting way to record one's secrets. This may prove a challenge to decipher.\n\nThank you for bringing this to me.", objectives = "Bring the Constellan Writ to Ve'nari at Ve'nari's Refuge.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63133] = { id = 63133, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shifting Cryptogram", description = "<The ever-shifting facets of the cube are inlaid with runes you cannot read. \n\nVe'nari may have an interest in it.>", completion = "Ah, I have not seen these runes used in quite some time. An ancient broker method of encryption.\n\nThis will be useful should I ever intercept cartel communications.", objectives = "Bring the Shifting Cryptogram to Ve'nari at Ve'nari's Refuge.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63134] = { id = 63134, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mawsworn Patrol Map", description = "<A diagram outlining Mawsworn movement patterns has been scrawled onto the parchment.\n\nVe'nari may find this useful.>", completion = "Valuable information, indeed. This will help me avoid detection whenever I must leave the safety of the refuge.\n\nI trust you've already committed the patrols to memory, Maw Walker.", objectives = "Bring the Mawsworn Patrol Map to Ve'nari at Ve'nari's Refuge.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63135] = { id = 63135, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Coldheart Flight Routes", description = "<These diagrams contain detailed information concerning the patrols of the Mawsworn Kyrian. \n\nVe'nari would relish this knowledge.>", completion = "This will help mitigate the Mawsworn's aerial advantage. Caution must still be exercised, of course.\n\nDo try to avoid their notice whenever possible. I would hate for one of them to follow you here.", objectives = "Bring the Coldheart Flight Routes to Ve'nari at Ve'nari's Refuge.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63136] = { id = 63136, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chaotic Runes", description = "<A series of unintelligible lines has been inscribed onto ancient parchment. \n\nVe'nari would value this.>", completion = "Ah, yes. These were clearly written by someone in the grip of madness.\n\nThat is not to say that they are nonsense, however. Sometimes, only the insane can see the truth.", objectives = "Bring the Chaotic Runes to Ve'nari at Ve'nari's Refuge.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63137] = { id = 63137, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Puzzling Cryptogram", description = "<The markings on each side of the cube periodically switch positions. \n\nVe'nari will be interested in this.>", completion = "<Ve'nari laughs as she appraises the cryptogram.>\n\nThis... is a children's toy. Brokers use them to teach their cartel's encryption methods.\n\nNot to say that this is worthless. Quite the contrary. In a place such of this, even a glimmer of mirth is valuable beyond measure.", objectives = "Bring the Puzzling Cryptogram to Ve'nari at Ve'nari's Refuge.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63140] = { id = 63140, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worn Obleron Etching", description = "<The etching on the crumbling manuscript hints at the origins of the Maw. \n\nVe'nari would be fascinated by this.>", completion = "<Ve'nari glances over the manuscript.>\n\nThis is truly an ancient document. A pity it is in such poor condition. The secrets it holds must be priceless.", objectives = "Bring the Worn Obleron Etching to Ve'nari at Ve'nari's Refuge.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63142] = { id = 63142, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Soulforge Blueprints", description = "<As you scan the documents in your possession, you realize that they outline the horrific methods by which souls can be forged into armaments. \n\nVe'nari would be intrigued by this.>", completion = "Raw materials must be hard to come by in the Maw. It does not surprise me that the Jailer's weaponsmiths would need to be... resourceful.\n\nPerhaps the knowledge recorded in these blueprints should remain a secret.", objectives = "Bring the Soulforge Blueprints to Ve'nari at Ve'nari's Refuge.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63145] = { id = 63145, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shadebound Testimonial", description = "<These appear to be the pain-induced ramblings of a tormented Torghast prisoner. \n\nVe'nari would find value in this.>", completion = "Quite the find, Maw Walker. Firsthand information from within Torghast is rare and valuable. None who set foot in the tower return to tell the tale.\n\nPresent company excluded, of course.", objectives = "Bring the Shadebound Testimonial to Ve'nari at Ve'nari's Refuge.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63152] = { id = 63152, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Venthyr Concordat", description = "<This appears to be an encoded correspondence between a venthyr noble and a Mawsworn lieutenant.\n\nPerhaps Ve'nari can decipher it.>", completion = "<Ve'nari glances over the scroll, rotating it in various directions.>\n\nIt has been some time since I've seen a method of encryption so intricate. But I suppose the venthyr are nothing if not ostentatious.\n\nWhatever the contents of this message might be, it is clear that its author wanted to keep it clandestine.", objectives = "Bring the Venthyr Concordat to Ve'nari at Ve'nari's Refuge.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63153] = { id = 63153, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Discarded Torments", description = "<The torn and faded pages depict punishments deemed too lenient and therefore disposed of. \n\nVe'nari may wish to study them.>", completion = "Ah, a rare bit of insight into the minds of the Maw's eternal tormentors.\n\nQuite fascinating... if a bit frightening.", objectives = "Bring the Discarded Torments to Ve'nari at Ve'nari's Refuge.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63154] = { id = 63154, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shadehound Armor Plating", description = "<The salvaged piece of plating is covered in runes that slowly shift and flow across its surface. \n\nVe'nari would be interested in studying this.>", completion = "An interesting artifact indeed, Maw Walker.\n\n<Ve'nari gently taps the armor.>\n\nYou can almost hear the screams of the souls who were consumed to forge it.", objectives = "Bring the Shadehound Armor Plating to Ve'nari at Ve'nari's Refuge.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63155] = { id = 63155, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Indecipherable Map", description = "<The map is covered in scribbles and notations that hint at realms unknown. \n\nVe'nari would likely find this fascinating.>", completion = "<Ve'nari raises the map, inspecting it closely.>\n\nAnd these stains--you said they were here when you found it?", objectives = "Bring the Indecipherable Map to Ve'nari at Ve'nari's Refuge.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63156] = { id = 63156, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mawsworn Shackles", description = "<The shackles are part tangible, part ethereal. They scream into your mind when held. \n\nJust the sort of thing Ve'nari might be looking for.>", completion = "<Ve'nari snatches the shackles from your hands.>\n\nRather dangerous for a mortal such as yourself to be carrying these around.\n\n<Ve'nari lifts and lowers the shackles slowly, as if to determine the weight.>\n\nThough I must admit... these could prove useful.", objectives = "Bring the Mawsworn Shackles to Ve'nari at Ve'nari's Refuge.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63157] = { id = 63157, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Box of Torments", description = "<The insidious music box hums an endlessly repeating set of dissonant chords. \n\nVe'nari may find it melodious.>", completion = "How soothing.\n\n<Ve'nari takes a closer look at the item in her hands.>\n\nI wonder...\n\n<Ve'nari presses a diamond shaped etching on the side of the box. It clicks into place, then opens to reveal a secret compartment containing a small piece of rolled up parchment.>\n\nNothing is what it seems, Maw Walker.", objectives = "Bring the Box of Torments to Ve'nari at Ve'nari's Refuge.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63158] = { id = 63158, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wailing Coin", description = "<The odd coin appears to be from a forgotten time. As you hold it, you are haunted by the cries of suffering souls. \n\nVe'nari may recognize the coin's value.>", completion = "An intriguing piece of currency.\n\nI would be most interested to learn how it was minted...", objectives = "Bring the Wailing Coin to Ve'nari at Ve'nari's Refuge.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63159] = { id = 63159, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Words of the Warden", description = "<As far as you can tell, this is a faded segment of a desiccated journal scrawled in Warden Korrath's hand. \n\nVe'nari would find value in this.>", completion = "One can often find valuable information in the pages of an enemy's journal. You have done well to acquire this.", objectives = "Bring the Words of the Warden to Ve'nari at Ve'nari's Refuge.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63160] = { id = 63160, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Korrath's Grimoire: Aleketh", description = "<These appear to be a collection of pages from a tome studying the denizens of the Maw in unsettling detail. \n\nNo doubt Ve'nari would wish to peruse this.>", completion = "I believe I have seen the creatures described in these pages before. \n\nFrom afar, of course. Always from afar.", objectives = "Bring the Korrath's Grimoire: Aleketh to Ve'nari at Ve'nari's Refuge.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63161] = { id = 63161, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Korrath's Grimoire: Belidir", description = "<These appear to be a collection of pages from a tome studying the denizens of the Maw in unsettling detail. \n\nNo doubt Ve'nari would wish to peruse this.>", completion = "Ah, yes. This will make for a fascinating study.", objectives = "Bring the Korrath's Grimoire: Belidir to Ve'nari at Ve'nari's Refuge.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63162] = { id = 63162, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Korrath's Grimoire: Gyadrek", description = "<These appear to be a collection of pages from a tome studying the denizens of the Maw in unsettling detail. \n\nNo doubt Ve'nari would wish to peruse this.>", completion = "Despite how long I have been here, there is still much about the creatures of the Maw that remains unknown to me.\n\nSometimes I have to wonder if it is better that way.", objectives = "Bring the Korrath's Grimoire: Gyadrek to Ve'nari at Ve'nari's Refuge.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63163] = { id = 63163, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tormentor's Notes", description = "<The crumpled and singed page describes the Mawsworn's preferred methods of interrogation and subjugation. \n\nVe'nari may find it of interest.>", completion = "Quite the vivid description.\n\nI suggest you consider this a reminder of what will happen should you fail in your efforts against the Jailer.", objectives = "Bring the Tormentor's Notes to Ve'nari at Ve'nari's Refuge.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63164] = { id = 63164, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mawsworn Orders", description = "<The document outlines a set of orders issued by Warden Korrath. \n\nVe'nari would find this illuminating.>", completion = "Well done, Maw Walker. These will allow us to better anticipate the enemy's actions.", objectives = "Bring the Mawsworn Orders to Ve'nari at Ve'nari's Refuge.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63166] = { id = 63166, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Shadowed Fate", description = "The Mawsworn... torture and torment souls within Ruin's Cradle.\n\nI... barely escaped, but I'm afraid I won't last long.\n\nTheir twisted rituals... breaking souls to serve as wretched shades. \n\nSpare them this fate!", completion = "You have... saved these souls from a terrible fate.\n\nEven a... true end... cannot be worse than this torment...", objectives = "Free 6 Tormented Souls in Ruin's Cradle by stomping out the Circles of Agony binding them.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63168] = { id = 63168, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Path of Ascension: Echthra", description = "Your soulbinds request your strategic mind in another trial.\n\nTheir sights this week are set on Echthra, that they may learn from the lessons her memory teaches.\n\nWhen you are able, report to Artemede to return to the Path of Ascension. Aid your soulbinds in defeating Echthra to prove their growth.", completion = "Congratulations on the victory. I look forward to hearing what your soulbinds have learned.", objectives = "Defeat Echthra in the Path of Ascension with any soulbind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63169] = { id = 63169, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Path of Ascension: Alderyn and Myn'ir", description = "Your soulbinds request your strategic mind in another trial.\n\nTheir sights this week are set on Alderyn and Myn'ir, that they may learn from the lessons their memories teach.\n\nWhen you are able, report to Artemede to return to the Path of Ascension. Aid your soulbinds in defeating Alderyn and Myn'ir to prove their growth.", progress = "Alderyn and Myn'ir's dedication and focus can teach us much.", completion = "Congratulations on the victory. I look forward to hearing what your soulbinds have learned.", objectives = "Defeat Alderyn and Myn'ir in the Path of Ascension with any soulbind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63170] = { id = 63170, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Path of Ascension: Nuuminuuru", description = "Your soulbinds request your strategic mind in another trial.\n\nTheir sights this week are set on Nuuminuuru, that they may learn from the lessons their memory teaches.\n\nWhen you are able, report to Artemede to return to the Path of Ascension. Aid your soulbinds in defeating Nuuminuuru to prove their growth.", completion = "Congratulations on the victory. I look forward to hearing what your soulbinds have learned.", objectives = "Defeat Nuuminuuru in the Path of Ascension with any soulbind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
