quests[63175] = { id = 63175, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Path of Ascension: Athanos", description = "Your soulbinds request your strategic mind in another trial.\n\nTheir sights this week are set on Athanos, that they may learn from the lessons his memory teaches.\n\nWhen you are able, report to Artemede to return to the Path of Ascension. Aid your soulbinds in defeating Athanos to prove their growth.", completion = "Congratulations on the victory. I look forward to hearing what your soulbinds have learned.", objectives = "Defeat Athanos in the Path of Ascension with any soulbind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63176] = { id = 63176, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Path of Ascension: Azaruux", description = "Your soulbinds request your strategic mind in another trial.\n\nTheir sights this week are set on Azaruux, that they may learn from the lessons their memory teaches.\n\nWhen you are able, report to Artemede to return to the Path of Ascension. Aid your soulbinds in defeating Azaruux to prove their growth.", completion = "Congratulations on the victory. I look forward to hearing what your soulbinds have learned.", objectives = "Defeat Azaruux in the Path of Ascension with any soulbind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63179] = { id = 63179, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drowned and Torn Asunder", description = "Maw Walker! I am relieved to see you in this place.\n\nA dark sect of kyrian who have allied themselves with the Maw stole my brothers and sisters from their posts in Bastion. They turned us over to a foul sea witch, the likes of which I've never seen.\n\nThis... Helya, I believe they called her... seems determined to break us so that we might also join her ranks.\n\nPlease, if you can, save my brethren.", completion = "We are in your debt, Maw Walker.\n\nI don't know if we will ever escape this place, but you have at least bought us a chance to strike back at our foes.", objectives = "Free 8 Drowning Kyrian in Gorgoa, the River of Souls.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63181] = { id = 63181, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Path of Ascension: Artemede's Challenge", description = "Are you prepared for a challenge, {name}?\n\nIt seems Pelagos has been struggling with his trials. I believe, with your guidance, some extra training on the Path is just what he needs!\n\nAthanos has many lessons to teach. With your aid, Pelagos can achieve victory and new experience to meditate on.", completion = "I knew you would rise to the challenge. Well done.", objectives = "Defeat Athanos as Pelagos in a Trial of Loyalty or higher in the Path of Ascension.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63182] = { id = 63182, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Path of Ascension: Artemede's Challenge", description = "Are you prepared for a challenge, {name}?\n\nPelagos's time spent in Ardenweald taught him many lessons. I would like to witness what he has learned.\n\nA trial against Nuuminuuru should allow him this chance. With your aid, Pelagos can achieve victory and new experience to meditate on.", progress = "Are you up for the challenge?", completion = "I knew you would rise to the challenge. Well done.", objectives = "Defeat Nuuminuuru as Pelagos in a Trial of Loyalty or higher in the Path of Ascension.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63184] = { id = 63184, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Path of Ascension: Artemede's Challenge", description = "Are you prepared for a challenge, {name}?\n\nMikanikos has requested an additional trial to train Bron. Splinterbark Nightmare's memory was captured with the help of his praetors, and should prove a worthy challenge for his goliath.\n\nWith your guidance, Mikanikos and Bron can overcome another trial.", completion = "I knew you would rise to the challenge. Well done.", objectives = "Defeat Splinterbark Nightmare as Mikanikos in a Trial of Loyalty or higher in the Path of Ascension.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63185] = { id = 63185, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Path of Ascension: Artemede's Challenge", description = "Are you prepared for a challenge, {name}?\n\nKleia is ready for another challenge. She is hungry to get back to the Path so she may exercise her new abilities further.\n\nEchthra's memory shall provide her with new lessons. With your aid, Kleia can overcome this challenge and incorporate its lessons into her eternal training.", progress = "Are you up for the challenge?", completion = "I knew you would rise to the challenge. Well done.", objectives = "Defeat Echthra as Kleia in a Trial of Loyalty or higher in the Path of Ascension.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63186] = { id = 63186, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Path of Ascension: Artemede's Challenge", description = "Are you prepared for a challenge, {name}?\n\nKleia is ready for another challenge. She is hungry to get back to the Path so she may exercise her new abilities further.\n\nIf she is to bear souls across the veil, she will need be prepared to contend against devourers like Azaruux. With your aid, Kleia can overcome this challenge and incorporate its lessons into her eternal training.", completion = "I knew you would rise to the challenge. Well done.", objectives = "Defeat Azaruux as Kleia in a Trial of Loyalty or higher in the Path of Ascension.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63187] = { id = 63187, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Path of Ascension: Artemede's Challenge", description = "Are you prepared for a challenge, {name}?\n\nMikanikos has requested an additional trial to train Bron. Mad Mortimer's memory should prove a good challenge, as he and Mikanikos share a mind with a passion to further their research.\n\nWith your guidance, Mikanikos and Bron can overcome another trial.", completion = "I knew you would rise to the challenge. Well done.", objectives = "Defeat Mad Mortimer as Mikanikos in a Trial of Loyalty or higher in the Path of Ascension.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63188] = { id = 63188, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Path of Ascension: Artemede's Challenge", description = "Are you prepared for a challenge, {name}?\n\nThenios has requested a Trial of Wisdom to exercise your strategic mind, as well as your soulbinds' abilities.\n\nA trial against Alderyn and Myn'ir shall suffice. Let us see you and your soulbinds can do.", progress = "Are you up for the challenge?", completion = "I knew you would rise to the challenge. Well done.", objectives = "Defeat Alderyn and Myn'ir in a Trial of Wisdom in the Path of Ascension.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63189] = { id = 63189, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Path of Ascension: Artemede's Challenge", description = "Are you prepared for a challenge, {name}?\n\nThenios has requested a Trial of Wisdom to exercise your strategic mind, as well as your soulbinds' abilities.\n\nA trial against Thran'tiok shall suffice. Let us see you and your soulbinds can do.", completion = "I knew you would rise to the challenge. Well done.", objectives = "Defeat Thran'tiok in a Trial of Wisdom in the Path of Ascension.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63190] = { id = 63190, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Path of Ascension: Artemede's Challenge", description = "Are you prepared for a challenge, {name}?\n\nThough most kyrian have their preferences, every kyrian must learn to fight with a multitude of weapons and equipment. This allows them to keep both their minds sharp and their muscles and movements honed.\n\nLet us see how your soulbinds fare against the memory of Craven Corinth while utilizing the Ring of Warding.", completion = "I knew you would rise to the challenge. Well done.", objectives = "Defeat Craven Corinth with the Ring of Warding in a Trial of Loyalty or higher in the Path of Ascension.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63191] = { id = 63191, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Path of Ascension: Artemede's Challenge", description = "Are you prepared for a challenge, {name}?\n\nThough most kyrian have their preferences, every kyrian must learn to fight with a multitude of weapons and equipment. This allows them to keep both their minds sharp and their muscles and movements honed.\n\nLet us see how your soulbinds fare against the memory of Kalisthene while utilizing the Spiritforged Aegis.", progress = "Are you up for the challenge?", completion = "I knew you would rise to the challenge. Well done.", objectives = "Defeat Kalisthene with the Spiritforged Aegis in a Trial of Loyalty or higher in the Path of Ascension.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63192] = { id = 63192, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Path of Ascension: Trial of Humility", description = "Are you prepared for a challenge, {name}?\n\nMany kyrian struggle with their trials of humility at some point along their path. It is important to remember that we can always be learning and improving, no matter how far we have come. But as we continue training, we can overcome more obstacles than before.\n\nIt is time for your soulbinds to be reminded of this lesson. Let us witness you all succeed in a Trial of Humility.", completion = "I knew you would rise to the challenge. Well done.", objectives = "Overcome a Trial of Humility in the Path of Ascension.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63197] = { id = 63197, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[63206] = { id = 63206, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Soulless Husks", description = "Some of the Mawsworn begin as inanimate suits of armor, forged by the stygian smiths of Zovaal's Cauldron. Once fashioned, they await infusion of a decrepit shade to complete their genesis.\n\nIt is at this time they are the most vulnerable, and so it is then you should strike.\n\nThe hammers wielded by the Mawsworn runesmiths hold the power to break as well as they shape. Procure one of them and smash our foes to dust before they can rise against us.", progress = "Have you satisfactorily dismantled our enemies?", completion = "Satisfying, is it not?\n\nThe fewer Mawsworn to rise into the Jailer's ranks, the better for our continued existence.", objectives = "Obtain a Stygian Hammer from a Stygian Runesmith and destroy 10 Armored Husks in Zovaal's Cauldron.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63208] = { id = 63208, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Next Step", description = "Your efforts have not gone unnoticed, but there are other realms that still require your aid.\n\nConsider the next step in your journey, mortal.", completion = "A wise decision. See to it that they receive your aid swiftly.", objectives = "Choose where to go in the Shadowlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63209] = { id = 63209, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Furthering the Purpose", description = "There are realms which still require your aid, mortal.\n\nYou must journey to one of their realms and ensure they stand strong.\n\nWhere will you go next?", completion = "May your efforts prove fruitful.", objectives = "Choose where to go in the Shadowlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63210] = { id = 63210, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Last Step", description = "Just one realm remains which requires your aid, mortal.\n\nSpeak with me when you are ready, and I shall inform you further.\n\nSuch is the Purpose.", completion = "Good luck.", objectives = "Choose where to go in the Shadowlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63211] = { id = 63211, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report to Adrestes", description = "You have chosen well.\n\nThe Kyrian have long ferried souls across the veil into the Shadowlands, ensuring a steady supply of anima for all the realms.\n\nTheir sacred purpose must be kept strong. Speak with Polemarch Adrestes and begin your future with your covenant.", completion = "Hail, Maw Walker.", objectives = "Report to Polemarch Adrestes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63212] = { id = 63212, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report to Mevix", description = "You have chosen well.\n\nThe Necrolords, eternal protectors of the Shadowlands, must remain strong to ensure we may continue to fulfill the Purpose.\n\nAid them as best you can. Speak with Secutor Mevix and begin your future with your covenant.", completion = "I knew you would return.", objectives = "Report to Secutor Mevix.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63213] = { id = 63213, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Naladu the Elder", objectives = "A traitor's debt can never be fully paid, Maw Walker. But penance can be earned in service and pain.\n\nTake a portion of my power with you, Maw Walker. Allow me that small step towards atonement.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63214] = { id = 63214, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report to Moonberry", description = "You have chosen well.\n\nThe Night Fae fill a critical role in the eternal cycle of nature spirits. The balance of many worlds depends on their work.\n\nSpeak with Lady Moonberry and begin your future with your covenant.", completion = "You're back! I knew you would choose us!", objectives = "Report to Lady Moonberry.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63215] = { id = 63215, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report to Draven", description = "You have chosen well.\n\nThe Venthyr must return to their duty helping souls atone for their sins, saving them from an eternity in the Maw.\n\nDenathrius's treachery must be righted. Speak with General Draven and begin your future with your covenant.", completion = "A wise choice.", objectives = "Report to General Draven.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63340] = { id = 63340, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sinfall Veteran", description = "Sinfall's influence grows thanks to your triumphs, {name}!\n\nYour accomplishments have not gone unnoticed, even beyond the borders of Revendreth.\n\nTales of your victories have echoed through the halls of Oribos. Zo'sorg, the Master of Conflict, has requested a meeting with you in the Enclave.\n\nThey have a keen interest in the art of war. I suggest you don't keep them waiting.", completion = "Ah, {name}. I have heard many stories of your prowess on the battlefield. \n\nI have interest in keeping great combatants like yourself well equipped. Zo'dash is authorized to further upgrade your armor and weapons.", objectives = "Meet with Zo'sorg in the Enclave in Oribos.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63341] = { id = 63341, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sinfall Tactician", description = "Sinfall is gaining more respect than Denathrius could have ever hoped to earn! It is all thanks to your efforts, {name}.\n\nZo'sorg has once again requested your presence in Oribos. Go at once.\n\nThe favor of Cartel Zo is not something we want to squander. A broker clan's trust is not one effortlessly gained.\n\nPerhaps they have more rewards to bestow upon you.", completion = "I see your skills in combat have improved even further. I trust you have made good use of our previous offer? \n\nZo'dash is now instructed to offer the full suite of his services to you. I look forward to seeing their impact on your performance.", objectives = "Meet with Zo'sorg in the Enclave in Oribos.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63342] = { id = 63342, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Necrolord Veteran", description = "The might of the Necrolords grows thanks to you, {name}.\n\nYour accomplishments have not gone unnoticed, even beyond the borders of Maldraxxus.\n\nTales of your victories have echoed through the halls of Oribos. Zo'sorg, the Master of Conflict, has requested a meeting with you in the Enclave.\n\nThey have a keen interest in the art of war. I suggest you don't keep them waiting.", completion = "Ah, {name}. I have heard many stories of your prowess on the battlefield. \n\nI have interest in keeping great combatants like yourself well equipped. Zo'dash is authorized to further upgrade your armor and weapons.", objectives = "Meet with Zo'sorg in the Enclave in Oribos.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63343] = { id = 63343, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Necrolord Tactician", description = "You have brought great honor to the Necrolords. Such honor attracts the attention of others yet again.\n\nZo'sorg has once again requested your presence in Oribos. Go at once.\n\nThe favor of Cartel Zo is not something we want to squander. A broker clan's trust is not one effortlessly gained.\n\nPerhaps they have more rewards to bestow upon you.", completion = "I see your skills in combat have improved even further. I trust you have made good use of our previous offer? \n\nZo'dash is now instructed to offer the full suite of his services to you. I look forward to seeing their impact on your performance.", objectives = "Meet with Zo'sorg in the Enclave in Oribos.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63344] = { id = 63344, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kyrian Veteran", description = "Bastion is healing thanks to you, {name}. The path is clear.\n\nYour accomplishments have not gone unnoticed, even beyond the borders of Bastion.\n\nTales of your victories have echoed through the halls of Oribos. Zo'sorg, the Master of Conflict, has requested a meeting with you in the Enclave.\n\nThey have a keen interest in the art of war. I suggest you don't keep them waiting.", completion = "Ah, {name}. I have heard many stories of your prowess on the battlefield. \n\nI have interest in keeping great combatants like yourself well equipped. Zo'dash is authorized to further upgrade your armor and weapons.", objectives = "Meet with Zo'sorg in the Enclave in Oribos.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63345] = { id = 63345, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kyrian Tactician", description = "Look around you, {name}. Elysian Hold stands as a testament to the progress we have made thanks to you.\n\nZo'sorg has once again requested your presence in Oribos. Go at once.\n\nThe favor of Cartel Zo is not something we want to squander. A broker clan's trust is not one effortlessly gained.\n\nPerhaps they have more rewards to bestow upon you.", completion = "I see your skills in combat have improved even further. I trust you have made good use of our previous offer? \n\nZo'dash is now instructed to offer the full suite of his services to you. I look forward to seeing their impact on your performance.", objectives = "Meet with Zo'sorg in the Enclave in Oribos.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63346] = { id = 63346, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Night Fae Veteran", description = "Ardenweald is safer than it has been in quite some time, thanks to you.\n\nYour accomplishments have not gone unnoticed, even beyond the borders of Ardenweald.\n\nTales of your victories have echoed through the halls of Oribos. Zo'sorg, the Master of Conflict, has requested a meeting with you in the Enclave.\n\nThey have a keen interest in the art of war. I suggest you don't keep them waiting.", completion = "Ah, {name}. I have heard many stories of your prowess on the battlefield. \n\nI have interest in keeping great combatants like yourself well equipped. Zo'dash is authorized to further upgrade your armor and weapons.", objectives = "Meet with Zo'sorg in the Enclave in Oribos.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63347] = { id = 63347, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Night Fae Tactician", description = "Your bravery has allowed Ardenweald to grow once again. It has also once again drawn the attention of brokers.\n\nZo'sorg has once again requested your presence in Oribos. Go at once.\n\nThe favor of Cartel Zo is not something we want to squander. A broker clan's trust is not one effortlessly gained.\n\nPerhaps they have more rewards to bestow upon you.", completion = "I see your skills in combat have improved even further. I trust you have made good use of our previous offer? \n\nZo'dash is now instructed to offer the full suite of his services to you. I look forward to seeing their impact on your performance.", objectives = "Meet with Zo'sorg in the Enclave in Oribos.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63418] = { id = 63418, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Exploited Explorers", description = "Chuck explains that something weird is happening in the jungle, and that his  group has been captured by wild fungarians.\n\nHe asks you to rescue his friends to help find out what's going on with the jungle.", objectives = "Rescue Chuck's friends", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63419] = { id = 63419, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spores Galore", description = "Chuck goes over again how the jungle seems to be alive and all wrong.\n\nHe asks you to recover the spores that are on the fungarians and the beasts they've infected.\n\nChuck is worried whatever is happening isn't natural.", objectives = "Collect 12 strange", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63435] = { id = 63435, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Temple Throwdown", description = "My parents are busy defending the Shrine of the... Eight... Coconuts? I wasn't paying attention. That's probably why they left me here.\n\nThey told me I could train with the big white cat! I'm going to be a ninja!\n\n<Anthea kicks several times in your direction.>\n\nYa! Kya! You better watch out!\n\n...\n\nI'm bored, do you want to pet battle? I brought all of my favorite pets with me.", progress = "I'm gonna get you!\n\n<Anthea punches the air several times.>\n\n Biff! Pow!", completion = "Ok, you win. Here's something I traded one of the grummle for. Have you met the grummle? They don't like it when I scratch behind their ears, but I do it anyway! They're just so cute!", objectives = "Defeat Anthea in a pet battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63447] = { id = 63447, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fear No Evil", description = "Have you embraced the Holy Light yet, <brother/sister>? It is through the Holy Light that we are saved! It is through the Holy Light that I am able to heal these overly demanding soldiers! And it is through the Holy Light that you will be able to venture out into the field to the north and rescue our fallen brothers!\n\nTake this prayer book with you into the field and cast the Light's healing touch on the injured.", completion = "I think you now understand the power of the Light. The Light giveth hope, brother and the Light taketh from the darkness! BLESSED BE THE LIGHT!", objectives = "Revive 4 Injured Stormwind Soldiers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63455] = { id = 63455, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dead On Their Feet", description = "As the Jailer twists the souls here to his will, there are still some that continue to resist him.\n\nI shall give you the ability to aid them in their resistance. Through Necrotic Cohesion we shall bind the runes, armor, and bones that reside here to create bodies for these souls. Bodies that will allow them to fight for us and their freedom!\n\nBind the Zealous souls and build us an army!", completion = "Excellent, {name}. Your efforts have bolstered our forces!", objectives = "Use the Cohesion Crystal to create bodies for 10 Defiant Souls.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63479] = { id = 63479, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Summons from the Matriarch", description = "Greetings, {name}.\n\nLet us not mince words--you are urgently needed in Silvermoon. \n\nWe're experiencing a resurgence of Scourge in Quel'Thalas. With nothing to hold the Scourge in check, we'll soon be overrun. We must hold the line!\n\nMeet me in the Hall of Blood, and we will get you a full briefing.", completion = "Good, you made it.\n\nLet us begin.", objectives = "Meet Lady Liadrin in Silvermoon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63480] = { id = 63480, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Briefing", description = "We haven't much time. \n\nThe Scourge have attacked Tranquillien, and there's nothing to hold them back.\n\nWe must take decisive action.", progress = "We will find a way.", completion = "We don't have time to waste.", objectives = "Listen to the briefing.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63481] = { id = 63481, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tranquillien Besieged", description = "Rommath has opened the way for us to quickly travel to Tranquillien. I warn you, it's already a bloody battlefield.\n\nTake the portal, and I will be along right after you.\n\nAnd {name}... keep an eye on Salandria. She may have excelled in her training thus far, but she has yet to be tested like this.", completion = "Not a moment too soon.\n\nLet's get to work.", objectives = "Take the portal to Tranquillien.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63482] = { id = 63482, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Death to the Scourge", description = "I haven't seen Scourge mustering in numbers like this since...\n\n<Liadrin shakes her head, steeling herself.>\n\nNever mind. There's no use dwelling in the past.\n\nOur first priority is thinning their numbers enough that we can find out what--or who--is really behind this attack. \n\nSlay as many of the undead as you can.", progress = "Once we've thinned out the numbers of the Scourge, we can strike at Vorath in his lair.", completion = "Well struck. \n\nBut for every undead we strike down, more come. We must find a way to stop them at their source.", objectives = "Slay Scourge in Tranquillien.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63483] = { id = 63483, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magus Installation", description = "This is no mindless strike... I have a strong suspicion that some powerful entity is manipulating the Scourge.\n\nEver since the Helm of Domination was shattered, there has been a conceivable risk that someone else could exert their will and assume control over the undead--at least temporarily.\n\nRommath and I can help defend Tranquillien, but we need to break those lines. \n\nClear a spot for us. Let us see if we can draw out their leader.", progress = "Rommath and I are ready to help set up the wards, once you clear out a spot for us.", completion = "The wards are in place, and that should give us some breathing room.\n\nBut this san'layn has me worried.", objectives = "Help Aethas and Rommath set up defenses in Tranquillien.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63484] = { id = 63484, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Knight's Weapon", description = "It's clear that this san'layn has decided to use the Scourge to empower himself somehow. We can keep taking him out, but he will just keep coming back.\n\nWe need a weapon that can break him for good.\n\nI think I have a solution. Upstairs, you will find a newly forged ranseur. It has yet to be tempered with magic--we will need to unlock its full potential. It will be our instrument of the Light.", progress = "Have you acquired the ranseur?", completion = "Good. That's exactly what we need. \n\nNow it's time to temper this ranseur with enough power to destroy this san'layn once and for all.", objectives = "Collect the Ranseur from upstairs in Tranquillien.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63485] = { id = 63485, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Honest Heart", description = "If we are to defeat Vorath, we need to amplify the power of the ranseur. But we will not cut corners or impose our will to do it. That lesson has been learned.\n\nHowever, the kyrian of Bastion are masters of ushering souls to their proper places. Perhaps they would lend a fragment of their power to our cause.\n\nGo to Bastion, and find a way to empower the ranseur.", completion = "I suppose if one happened to die, this wouldn't be such a bad place to end up.\n\nThis kyrian says he will help us.", objectives = "Travel to Agthia's Repose in Bastion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63486] = { id = 63486, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Unbreakable Will", description = "We're clearly dealing with someone who is using terrible magic to suspend his own death.\n\nThere's another force we know of that uses magic in this fashion. The Maldraxxi are intimately familiar with the trappings of death, and equally familiar with how to subvert it. Perhaps one of the Houses knows of a way to help us.\n\nGo there, and seek out power that can break this unnatural loop.", completion = "We're not in Quel'Thalas anymore.\n\nLet's get what we need as quickly as we can--we've got no time to waste!", objectives = "Travel to the Theater of Pain in Maldraxxus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63487] = { id = 63487, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to the Ghostlands", description = "Such power! Surely not even Vorath can withstand the might of this weapon now. \n\nWe have what we came to the Shadowlands for. The ranseur is ready.\n\nLet's get back to Lady Liadrin in Tranquillien. I hope we're not too late to make a difference!", completion = "Now that you have the empowered ranseur, it's time to show our full might on the battlefield. \n\nAre you ready?", objectives = "Return to Lady Liadrin in Tranquillien.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63488] = { id = 63488, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I Am the Blade of the Light", description = "It's time to put all that power and training into the field.\n\nTake the empowered ranseur, and cut a swath of destruction through the Scourge!\n\nWe'll meet you at the doorstep of Deatholme.", completion = "He's here. We've driven the fiend back into his cage.\n\nNow to send him to his doom.", objectives = "Use the empowered ranseur to slay Scourge in the Dead Scar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63489] = { id = 63489, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Justice Long Overdue", description = "You made short work of the Scourge in the Dead Scar, but we've a bigger target to face. It's time to test the mettle of your weapon against Vorath.\n\nLet us finish this, together.", progress = "We will protect our homeland.", completion = "It's done. Already the Scourge are beginning to scatter.\n\nWe can dispose of the rest in time.", objectives = "Slay Vorath.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63490] = { id = 63490, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blood Knight", description = "The power of the ranseur has been spent, but we are victorious! With Vorath defeated, perhaps the Scourge will be more easily dealt with--thanks to you.\n\nMeet me back in Silvermoon. Your efforts and heroism today will not go unrecognized.", completion = "Congratulations, and well earned.", objectives = "Receive accolades from Lady Liadrin in Silvermoon City.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63494] = { id = 63494, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Anvil-Thane's Designs", description = "I see you eyein' our weapons here. Wouldnae ye know, I forged them myself!\n\nSo far, I've got designs for a staff, a one-handed axe, and a shield... I could make ye some, if you'd like!\n\nO' course, that's what I'd normally say. Unfortunately I lost the designs in a bet down at the Grim Guzzler. If ye could get them back, as well as gather the materials, I'd be happy to forge ye some weapons!", completion = "Ye lookin' to challenge me?", objectives = "Find who Thurgaden lost his plans to in the Grim Guzzler.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63498] = { id = 63498, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brawl or Brew", description = "Ach, Thurgaden sent ye did he? Ye'd think the Anvil-Thane would be made o' tougher stuff than the rest of this drunken lot, but I guess I was mistaken!\n\nIf ye want tae win back his designs, yer gonna have tae win 'em fair and square.\n\nI've only got one question left fer ye.\n\nBrawl? Or Brew?", progress = "Not a single dwarf in 'ere has beaten me. What makes ye different?", completion = "Ye put up a real challenge there! Take the plans, I dunnae how to read them anyway!", objectives = "Defeat Strongarm Jarden in one of her competitions.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63501] = { id = 63501, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's Called Borrowing", description = "<These complex blueprints detail Thurgaden's designs for his weaponry, but are hard to parse. Notes are scribbled in the margins in messy handwriting, listing modifications and notes Thurgaden left for himself.\n\nTwo notes in particular stand out to you. One denotes that he lent his engraving tool to the core hound trainer Kasea Angerforge, and the other wonders how many elementals they employ at the Grim Guzzler brewing operation.>", progress = "<Thurgaden is mumbling and cursing under his breath about how he will defeat Jarden in their next competition.>", completion = "Ye return, with my plans and materials at that! I bet ye knocked Jarden down a peg or two!", objectives = "Find 5 Darkforged Ingot, a Boiling Flamecore, and the Flamepoint Engraver around Shadowforge City.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63502] = { id = 63502, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weapons o' the Dark Iron", description = "One step left, friend. Lend me a hand in my craftin', then you'll have yer hands on the most powerful weapons forged in the deepest fires of Blackrock Mountain!", progress = "These weapons shall rival even my own!", completion = "These weapons'll put the fear an' shame into even a mindless undead colossus!", objectives = "Aid Anvil-Thane Thurgaden in crafting your new weapons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63519] = { id = 63519, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unfair Fight", description = "A cowardly pest that cheats his way out of the glory of death? Bah!\n\nI have something that'll cut him down where he stands. But such an enhancement requires one who is strong enough to wield it properly.\n\nShow me your mettle and fight! If you can prove yourself, I'll empower that ranseur of yours.", completion = "Here, take the power we've honed and use it to defeat your hardest-to-kill enemies.\n\nIf that san'layn ever shows up here, well... he'll have an appropriately warm welcome.", objectives = "Prove your strength to Fightlord San.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63522] = { id = 63522, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Fair Race", description = "A soul that refuses to cross the veil is a problem we kyrian are familiar with. I can help you.\n\nBut before I grant your weapon this power, I must know that you will not abuse it, and that your heart is true.\n\nLet us run a race. Along the course, ring the bells. If your heart is pure, they will aid your speed. You must have at least five bells recently rung in order to complete the race.\n\nDo not be distracted by shortcuts. And do not try to cheat to get ahead, it will not work.\n\nAre you ready?", completion = "Such a stubborn young knight. She... almost seems to dredge up a memory of long ago.\n\nHere, accept this gift of power. I wish you victory over your foe.", objectives = "Run an honest race with Vandellor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63543] = { id = 63543, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Necrolord Assault", description = "The Jailer's forces  have been caught off guard by our attack. We shall overrun Perdition Hold and defeat his champions at the Altar of Domination!\n\nYour help is needed Maw Walker. Assist our forces on the battlefield!", objectives = "Complete 1 quests in Perdition Hold and the Face of Oblivion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63545] = { id = 63545, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Putting A Plan Together", description = "While Maldraxxus pushes the main gate, we can take the side gate with the help of our Centurions.\n\nThe remains of many Corrupted Centurions taken by the Jailor litter this area. Their parts could be used to build new ones to help in the assault.\n\nSee if you can locate the parts we need to build a new Centurion.", progress = "Have you found the parts I requested?", completion = "These parts are more than enough to build a new Centurion!", objectives = "Deliver 3 Centurion Parts and 15 Automaton Bolts to Mikanikos", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63576] = { id = 63576, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The First Move", description = "While the covenants labor to defend the Shadowlands, the Jailer has not sat idle within Torghast. It seems he intends to set the next phase of his scheme into motion.\n\nPolemarch Adrestes has brought us disturbing news from Elysian Hold. He will recount what he witnessed once you arrive.\n\nMake haste. I fear that time grows short.", progress = "We will continue to fight.", completion = "Anduin... now the Jailer's pawn...\n\nWe must take immediate action, {name}. It is time for the covenants to convene.", objectives = "Speak with Polemarch Adrestes in Oribos.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63578] = { id = 63578, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Battle of Ardenweald", description = "With the betrayal of Sire Denathrius, and the absence of the Primus of Maldraxxus, we must assume that the Winter Queen is the Jailer's next target.\n\nAnd we won't let anyone take her sigil!\n\nArdenweald has endured much, but it is a realm of great and mysterious power. Things aren't always what they seem.\n\nWe'll use this to our advantage, no matter who comes for the Queen!", completion = "We just barely survived that! I definitely didn't expect THAT to happen.\n\nBut it's not over. We can't let our guard down!", objectives = "Protect the Winter Queen's sigil in the Battle of Ardenweald.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63579] = { id = 63579, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Paladin's Soul", progress = "Greetings Maw Walker. Your arrival is fortuitous.", completion = "I believe this soul fragment may be the key to Uther's recovery.", objectives = "Reclaim the Remnant of Justice from the Ossuary of the Banished in Torghast.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63580] = { id = 63580, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wounded Memories", description = "The arrival of Uther's wounded soul was the impetus for many events that led us to our current struggles.\n\nDevos's broken trust. Her involvement with Helya. The rise of the Forsworn.\n\nBastion needs to change, but we struggle to find a solution.\n\nPerhaps this soul fragment will provide valuable insight.", progress = "I have never seen a soul torn as Uther's has been.", completion = "Though Uther's soul is suffering, we must not lose hope.", objectives = "Help Uther forge a connection to the Remnant of Justice.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63581] = { id = 63581, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Step Into the Light", description = "It is as I feared.\n\nThis fragment of Uther's soul was darkened by the mourneblade that slew him. His memories are shattered and twisted.\n\nFor Uther to move past his pain, to move past his grief, he must experience his past once again.\n\nBut he does not have to do this alone.\n\nUsing my soul mirror, we can aid Uther in walking through these memories. He can then come to terms with the emotions they contain. We must help him see past the distortions and understand the truths they hold.", progress = "We can learn from this.", completion = "His memories are twisted and convoluted.\n\nI am sorry, Uther, but we must continue.", objectives = "Use the Soul Mirror to aid Uther in reliving his past.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63582] = { id = 63582, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "He Was My Student", description = "Uther's memories of this Prince Arthas haunt him deeply. He is the reason Uther's soul was fragmented, why Devos fell the way she did.\n\nThe pain in these memories is palpable.\n\nWe have to dig deeper. Uther must face the source of this darkness.\n\nOnce again, you need to enter his past to protect his future.", progress = "Uther needs our support.", completion = "The sting of betrayal haunts Uther deeply. But he can persevere.\n\nHe must!", objectives = "Aid Uther in reliving his second memory.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63583] = { id = 63583, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I Intend to Live Forever", description = "Please, {name}. I am not finished.\n\nThere is one more memory that I must see. One more that must be faced.\n\nIt... it will not be easy. I will need support from all of you.\n\nBut it must be done.", progress = "<Adrestes is deep in thought.>", completion = "<Adrestes breaks from his thoughts, a renewed resolve in his eyes.>\n\nI believe this experience was the missing piece for Uther. And for me as well.", objectives = "Aid Uther in reliving his final memory.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63584] = { id = 63584, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Triumphant Return", description = "This temple represents a new dawn for Bastion, {name}.\n\nThe Temple of Devotion will stand as a place of fellowship. We will work with the Forsworn, as well as aspirants and kyrian of all experience and backgrounds, to forge a future of which all can be proud.\n\nLet us return to Elysian Hold. I request that you join us for a momentous occasion--the ascension of a new Paragon and the creation of a new sigil.", completion = "Allow me to escort you to the Spires of Ascension, {name}.\n\nAs the new Polemarch of Bastion, it would be my honor.", objectives = "Meet Kalisthene at Elysian Hold. \n\nThe Kyrian Courier can provide a flight.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63585] = { id = 63585, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blind Loyalty", description = "The path forward for the kyrian is clear to me now.\n\nFirst we will speak with Nikolon. I urge you to stay and listen.\n\nAfterward, we must return to Elysian Hold.\n\nThere I will request an audience with the Archon, and I need you all by my side as I do so.", progress = "The kyrian must forge a new path.", completion = "<Adrestes bows his head deeply.>\n\nIt is an honor. But we have only just begun.", objectives = "Join Polemarch Adrestes at Elysian Hold for an audience with the Archon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63586] = { id = 63586, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Compassion in Devotion", description = "Our first order of business is to rededicate the Temple of Loyalty.\n\nPelagos has volunteered to stay here and help prepare for the ceremony. I requested that Nikolon bring his companions to meet us at Steward's Rest, to aid us in convincing some of the Forsworn of our new path.\n\nMeet us there when you are able.", completion = "Let us begin.", objectives = "Meet Adrestes at Steward's Rest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63587] = { id = 63587, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reclaimable Anima", description = "Mikanikos has explained much about Forsworn centurions to me, {name}.\n\nI cannot say that I understood all of it, but it seems he has not yet found a reliable way to return them to their proper operating standards.\n\nTheir anima can still be useful, though!\n\nAdrestes has focused on how to rededicate the temple, but not on his own safety. I worry the process will drain much of his anima.\n\nIf you can reclaim cores from the Forsworn centurions, we can use them as anima stores for Adrestes.", progress = "I've been working with Mikanikos on methods to reuse anima from Forsworn centurions. I can handle this!", completion = "Thank you, {name}. If Adrestes falters, I now have the anima to pick him back up.", objectives = "Collect 5 Tainted Centurion Cores from Forsworn centurions.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63588] = { id = 63588, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rebuilding Faith", description = "The Forsworn are lost, {name}.\n\nThey are like ghosts, haunting the Temple of Loyalty. Nowhere else to go. Leaderless, purposeless, abandoned.\n\nWe must show them that there is a path forward.\n\nLet me accompany you into the temple. Allow me to talk to them, speak to their sensibilities. Perhaps we can convince them to give Adrestes's new path a chance.", progress = "The Forsworn may have abandoned the Path, but we had good reason.", completion = "It will take time and communication to repair the trust that has been lost, {name}... but there is hope again.", objectives = "Convince 10 Forsworn to return to the Path.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63589] = { id = 63589, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Directing Dedication", description = "The five temples of Bastion have stood strong since its very creation. The idea of rededicating one has never been broached before, and will no doubt require a significant amount of anima.\n\nUnderneath this temple are stores of anima we rationed for the drought. Now that anima is returning, we can use these reserves for our purposes.\n\nYou will need to use channelers and collectors throughout the grounds to redirect anima to the top. That should give me the power I need.", progress = "We endeavor to perform a monumental feat, one that has never been attempted before.", completion = "It is heartening to see so much anima flowing again.", objectives = "Redirect anima from the Citadel of Loyalty to the temple.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63590] = { id = 63590, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Vesper Rings", description = "Loyalty shall no longer be a demanded tenet of the Path, but rather a virtue that is earned. A choice.\n\nWe must show devotion to those who struggle, whether they are recently arrived souls or peers who need our aid.\n\nIt will take all the anima at hand to rededicate this temple. And in so doing, to ring in a new age for the kyrian.\n\nI fear the Mawsworn may attempt to thwart our plans. Protect me during this ritual, {name}. We must see this through.", progress = "<Adrestes cannot be distracted as he uses every ounce of himself for the task at hand.>", completion = "Devotion... it is born of compassion. Of service.\n\nA worthy tenet indeed.", objectives = "Protect Polemarch Adrestes as he rededicates the Temple of Loyalty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63591] = { id = 63591, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Grand Reception", description = "{name}, you have aided the kyrian in the most trying of times. Your devotion to our cause has helped usher in a new beginning for all of us.\n\nWe would be honored if you would join us for a gathering prior to the ceremony. Many members of our covenant wish to express their appreciation for all you have done.\n\nThis is a day of great joy. I am so pleased that you are here to witness it!", completion = "The time of ceremony has come.", objectives = "Speak to Kalisthene to attend the gathering, then mingle with your soulbinds and the other kyrian.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63592] = { id = 63592, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The New Path", description = "Today, a new paragon is anointed. And for the first time since the dawn of our realm, a temple is rededicated to represent our devotion to one another.\n\nA new paragon, a new sigil, and a new path for all kyrian.\n\nThis ceremony shall be glorious indeed!", completion = "This honor is more than I could have hoped.\n\nThere is a long road ahead, but with the help of my fellow kyrian--all kyrian--the Temple of Devotion will embody the future of our people.\n\nLet the true work begin.", objectives = "Speak to Kalisthene to take part in the ceremony at the Seat of the Archon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63593] = { id = 63593, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "New Sigil of the Kyrian", description = "With a future of kinship and devotion secured for Bastion, a new sigil is born to represent our path forward.\n\nPlease report all that you have done to the Primus. When he is ready, we will deliver the sigil to him. \n\nLet us hope he can use it to thwart the Jailer's plan and save the Shadowlands.", completion = "Kyrestia was the first to be borne aloft by wings of duty and service.\n\nThat you have helped the Archon see a new path forward is a wondrous thing indeed, mortal.", objectives = "Report back to the Primus in Korthia.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63594] = { id = 63594, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clearing the Walls", description = "<This scroll shows the locations of a series of pylons, that protect Perdition Hold from assault.\n\nDestroying these Pylons could aid in the success of our attack>", progress = "Have you cleared the walls?", completion = "The defenses are broken! Most excellent, Maw Walker.", objectives = "Use the Overcharged Champion to destroy 6 Deadsoul Pylons along the walls of Perdition Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63603] = { id = 63603, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Yak Soul", description = "<The Yak Soul is cordial and resilient. The shape of the yak will be yours to call upon.>", completion = "Ah, the yak. This shape is now yours to call upon.", objectives = "Bring the Yak Soul to Lady Muunn in the Heart of the Forest.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[63604] = { id = 63604, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shoveltusk Soul", description = "<The Shoveltusk Soul is protective and determined. The shape of the shoveltusk will be yours to call upon.>", completion = "Ah, the shoveltusk. This shape is now yours to call upon.", objectives = "Bring the Shoveltusk Soul to Lady Muunn in the Heart of the Forest.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
