quests[63608] = { id = 63608, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hippo Soul", description = "<The Hippo Soul is ferocious. The shape of the hippo will be yours to call upon.>", completion = "Ah, the hippo. This shape is now yours to call upon.", objectives = "Bring the Hippo Soul to Lady Muunn in the Heart of the Forest.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
